window.GLOSARIO = {"variable aleatoria": {"t": "variable aleatoria", "d": "Una cantidad cuyo valor depende del resultado de un experimento aleatorio. Se escribe con mayúscula (X) para distinguirla de un valor concreto que tome (x).", "s": "X", "l": "estadistica/01-variables-aleatorias"}, "distribucion": {"t": "distribución", "d": "La descripción completa de qué valores puede tomar una variable aleatoria y con qué probabilidad. La PMF, la PDF y la CDF son tres formas de escribirla.", "s": "", "l": "estadistica/01-variables-aleatorias"}, "funcion de densidad": {"t": "función de densidad", "d": "Para una variable continua, la función f(x) cuya integral sobre un intervalo da la probabilidad de caer en ese intervalo. El valor f(x) en un punto no es una probabilidad.", "s": "f(x)", "l": "estadistica/02-pmf-cdf"}, "funcion de masa": {"t": "función de masa", "d": "Para una variable discreta, la función p(x) = P(X = x) que asigna a cada valor posible su probabilidad.", "s": "p(x)", "l": "estadistica/02-pmf-cdf"}, "esperanza": {"t": "esperanza", "d": "El promedio de una variable aleatoria ponderado por su probabilidad: E[X] = Σ x·p(x) en el caso discreto, ∫ x·f(x) dx en el continuo. También se llama valor esperado o media de la distribución.", "s": "E[X], μ", "l": "estadistica/04-esperanza-varianza-momentos"}, "varianza": {"t": "varianza", "d": "La esperanza del cuadrado de la desviación respecto a la media: Var(X) = E[(X − μ)²]. Mide dispersión, en unidades al cuadrado.", "s": "Var(X), σ²", "l": "estadistica/04-esperanza-varianza-momentos"}, "desviacion estandar": {"t": "desviación estándar", "d": "La raíz cuadrada de la varianza. Mide dispersión en las mismas unidades que la variable.", "s": "σ", "l": "estadistica/04-esperanza-varianza-momentos"}, "momento": {"t": "momento", "d": "El término β(x_k − x_{k−1}) que se suma al paso de descenso: arrastra la dirección anterior, cancela parte del zigzag y acumula avance en la dirección que se repite.", "s": "β", "l": "matematica/16-descenso-de-gradiente"}, "asimetria": {"t": "asimetría", "d": "El tercer momento estandarizado, E[((X − μ)/σ)³]. Vale 0 en una distribución simétrica; positivo si la cola larga está a la derecha.", "s": "γ₁", "l": "estadistica/04-esperanza-varianza-momentos"}, "curtosis": {"t": "curtosis", "d": "El cuarto momento estandarizado, E[((X − μ)/σ)⁴]. La curtosis en exceso le resta 3, que es el valor de la normal, para que la normal quede en 0.", "s": "γ₂", "l": "estadistica/04-esperanza-varianza-momentos"}, "estandarizar": {"t": "estandarizar", "d": "Restar la media y dividir entre la desviación estándar: z = (x − μ)/σ. El resultado no tiene unidades y tiene media 0 y desviación 1.", "s": "z", "l": "estadistica/04-esperanza-varianza-momentos"}, "media muestral": {"t": "media muestral", "d": "El promedio de los n datos observados: x̄ = (1/n) Σ xᵢ. Es una estimación de la esperanza μ, que en general no se conoce.", "s": "x̄", "l": "estadistica/04-esperanza-varianza-momentos"}, "varianza muestral": {"t": "varianza muestral", "d": "s² = (1/(n−1)) Σ (xᵢ − x̄)². Estima la varianza σ². El denominador n − 1 corrige el sesgo que introduce usar x̄ en lugar de la μ desconocida.", "s": "s²", "l": "estadistica/04-esperanza-varianza-momentos"}, "estimador": {"t": "estimador", "d": "Una fórmula que se aplica a la muestra para aproximar una cantidad de la población. x̄ es un estimador de μ; s² es un estimador de σ².", "s": "", "l": "estadistica/04-esperanza-varianza-momentos"}, "insesgado": {"t": "insesgado", "d": "Un estimador es insesgado si su esperanza coincide con la cantidad que estima: en promedio, sobre muchas muestras, acierta. Sesgo es la diferencia entre esa esperanza y el valor verdadero.", "s": "", "l": "estadistica/04-esperanza-varianza-momentos"}, "grados de libertad": {"t": "grados de libertad", "d": "El número de valores que pueden variar libremente después de imponer las restricciones. Al calcular s² se impone que las desviaciones sumen cero, así que de n desviaciones solo n − 1 son libres.", "s": "", "l": "estadistica/04-esperanza-varianza-momentos"}, "cancelacion catastrofica": {"t": "cancelación catastrófica", "d": "Pérdida de precisión en punto flotante al restar dos números casi iguales: los dígitos que coinciden se anulan y queda solo el ruido de redondeo.", "s": "", "l": "estadistica/04-esperanza-varianza-momentos"}, "covarianza": {"t": "covarianza", "d": "La esperanza del producto de las desviaciones de dos variables: Cov(X,Y) = E[(X − μₓ)(Y − μᵧ)]. Mide si tienden a desviarse en la misma dirección.", "s": "Cov(X,Y)", "l": "estadistica/05-covarianza-correlacion"}, "correlacion": {"t": "correlación", "d": "La covarianza dividida entre el producto de las desviaciones estándar. Es adimensional y vive en [−1, 1]. Mide solo asociación lineal.", "s": "ρ, r", "l": "estadistica/05-covarianza-correlacion"}, "independencia": {"t": "independencia", "d": "Dos variables son independientes si la distribución conjunta es el producto de las marginales: conocer una no cambia la distribución de la otra. Implica covarianza cero; lo contrario no es cierto.", "s": "", "l": "estadistica/05-covarianza-correlacion"}, "punto flotante": {"t": "punto flotante", "d": "La representación de números reales en la computadora con un número fijo de dígitos significativos (unos 16 en float64). Toda operación redondea.", "s": "", "l": "python/06-numpy-primer-contacto"}, "mediana": {"t": "mediana", "d": "El valor que deja la mitad de la probabilidad (o de los datos) a cada lado. A diferencia de la media, no se mueve por los valores extremos.", "s": "", "l": "estadistica/02-pmf-cdf"}, "poblacion": {"t": "población", "d": "El conjunto completo de unidades sobre las que se quiere concluir algo. Casi nunca se observa entera.", "s": "", "l": "estadistica/01-variables-aleatorias"}, "muestra": {"t": "muestra", "d": "Un subconjunto de la población del que sí se observan los valores. Su tamaño se escribe n.", "s": "n", "l": "estadistica/01-variables-aleatorias"}, "parametro": {"t": "parámetro", "d": "Un número que describe a la población, como μ o σ. Es fijo y desconocido; no se calcula, se estima.", "s": "μ, σ", "l": "estadistica/01-variables-aleatorias"}, "estadistico": {"t": "estadístico", "d": "Un número calculado a partir de la muestra, como x̄ o s. Cambia con cada muestra, así que es una variable aleatoria.", "s": "x̄, s", "l": "estadistica/01-variables-aleatorias"}, "distribucion muestral": {"t": "distribución muestral", "d": "Cómo se reparten los valores de un estadístico al repetir el muestreo muchas veces sobre la misma población.", "s": "", "l": "estadistica/01-variables-aleatorias"}, "error estandar": {"t": "error estándar", "d": "La desviación estándar de un estadístico entre muestras. Para la media vale σ/√n: baja con la raíz de n, no con n.", "s": "EE", "l": "estadistica/01-variables-aleatorias"}, "cdf": {"t": "cdf", "d": "La función de distribución acumulada F(x) = P(X ≤ x). Sirve igual para variables discretas y continuas, y por eso es la herramienta de diagnóstico del módulo.", "s": "F(x)", "l": "estadistica/02-pmf-cdf"}, "percentil": {"t": "percentil", "d": "El percentil q es el valor que deja una proporción q de la distribución por debajo. El rango percentil hace lo inverso: de un valor devuelve la proporción.", "s": "F⁻¹(q)", "l": "estadistica/02-pmf-cdf"}, "acumulada empirica": {"t": "acumulada empírica", "d": "La proporción de datos observados menores o iguales a x. Es una escalera con un escalón de 1/n en cada dato, y no depende de elegir intervalos.", "s": "F̂ₙ(x)", "l": "estadistica/02-pmf-cdf"}, "uniforme": {"t": "uniforme", "d": "Distribución en la que todos los valores de un intervalo son igual de probables. La uniforme en [0,1] es el punto de partida de casi toda simulación.", "s": "U", "l": "estadistica/02-pmf-cdf"}, "falta de memoria": {"t": "falta de memoria", "d": "Propiedad de una variable de espera: haber esperado ya cierto tiempo no cambia la distribución de lo que queda. Caracteriza a la exponencial y a ninguna otra distribución continua.", "s": "", "l": "estadistica/03-distribuciones-analiticas"}, "proceso de poisson": {"t": "proceso de poisson", "d": "Un flujo de eventos que ocurren a tasa constante e independientes entre sí. Los tiempos entre eventos consecutivos son exponenciales.", "s": "", "l": "estadistica/03-distribuciones-analiticas"}, "exponencial": {"t": "exponencial", "d": "Distribución de los tiempos de espera de un proceso sin memoria. Su complemento acumulado es e^(−λx), que es una recta en escala logarítmica vertical.", "s": "Exp(λ)", "l": "estadistica/03-distribuciones-analiticas"}, "lognormal": {"t": "lognormal", "d": "Distribución de una variable cuyo logaritmo es normal. Aparece cuando una cantidad se forma multiplicando muchos factores.", "s": "", "l": "estadistica/03-distribuciones-analiticas"}, "pareto": {"t": "pareto", "d": "Distribución de cola pesada cuyo complemento acumulado es una potencia de x. Es invariante de escala: su cola por encima de cualquier umbral es otra Pareto igual.", "s": "", "l": "estadistica/03-distribuciones-analiticas"}, "normal": {"t": "normal", "d": "Distribución acampanada y simétrica que aparece al sumar muchos efectos pequeños e independientes. Queda descrita por su media y su desviación.", "s": "N(μ, σ²)", "l": "estadistica/03-distribuciones-analiticas"}, "spearman": {"t": "spearman", "d": "Correlación calculada sobre los rangos en vez de sobre los valores. Detecta cualquier relación monótona, aunque sea curva.", "s": "", "l": "estadistica/05-covarianza-correlacion"}, "centrar": {"t": "centrar", "d": "Restar la media a cada valor. La variable centrada tiene media cero, y es la operación que convierte la estadística en geometría.", "s": "x̃", "l": "estadistica/05-covarianza-correlacion"}, "i.i.d.": {"t": "i.i.d.", "d": "Independientes e idénticamente distribuidas. Son dos condiciones distintas: que ninguna informe sobre las otras, y que todas salgan de la misma distribución.", "s": "", "l": "estadistica/06-teorema-central-limite"}, "teorema central del limite": {"t": "teorema central del límite", "d": "La suma estandarizada de n variables i.i.d. con media y varianza finitas converge a una normal estándar, sea cual sea la distribución de partida.", "s": "", "l": "estadistica/06-teorema-central-limite"}, "converge en distribucion": {"t": "converge en distribución", "d": "Que la función acumulada de una sucesión de variables tiende, en cada punto, a la acumulada de una variable límite.", "s": "→ᵈ", "l": "estadistica/06-teorema-central-limite"}, "cauchy": {"t": "cauchy", "d": "Distribución simétrica de colas tan pesadas que no tiene media ni varianza finitas. La media de n observaciones suyas es otra Cauchy con la misma dispersión.", "s": "", "l": "estadistica/06-teorema-central-limite"}, "sesgo": {"t": "sesgo", "d": "La diferencia entre el promedio de un estimador sobre todas las muestras posibles y el valor verdadero: E[θ̂] − θ. Vale cero si el estimador acierta en promedio.", "s": "", "l": "estadistica/07-estimacion"}, "error cuadratico medio": {"t": "error cuadrático medio", "d": "El promedio del cuadrado de la distancia entre el estimador y el valor verdadero: E[(θ̂ − θ)²]. Se descompone en sesgo al cuadrado más varianza.", "s": "ECM", "l": "estadistica/07-estimacion"}, "consistencia": {"t": "consistencia", "d": "La propiedad de un estimador cuyo error se hace arbitrariamente pequeño al crecer la muestra. Es distinta de la insesgadez: hay estimadores insesgados que no son consistentes.", "s": "", "l": "estadistica/07-estimacion"}, "verosimilitud": {"t": "verosimilitud", "d": "La probabilidad o densidad de los datos que se observaron, leída como función del parámetro con los datos fijos. No es una distribución sobre el parámetro: no integra uno.", "s": "L(θ)", "l": "estadistica/08-maxima-verosimilitud"}, "log-verosimilitud": {"t": "log-verosimilitud", "d": "El logaritmo de la verosimilitud. Tiene el máximo en el mismo sitio y convierte el producto en suma, lo que evita que se vuelva cero por underflow.", "s": "ℓ(θ)", "l": "estadistica/08-maxima-verosimilitud"}, "maxima verosimilitud": {"t": "máxima verosimilitud", "d": "Método para construir estimadores: se elige el valor del parámetro bajo el cual los datos observados serían lo más probables posible.", "s": "", "l": "estadistica/08-maxima-verosimilitud"}, "intervalo de confianza": {"t": "intervalo de confianza", "d": "Un intervalo cuyos extremos se calculan de la muestra, construido para contener al parámetro con probabilidad 1 − α. Lo aleatorio son los extremos, no el parámetro.", "s": "", "l": "estadistica/09-intervalos-de-confianza"}, "cobertura": {"t": "cobertura", "d": "La probabilidad real de que un intervalo contenga el parámetro. La nominal es la que el método anuncia; no siempre coinciden.", "s": "", "l": "estadistica/09-intervalos-de-confianza"}, "distribucion t de student": {"t": "distribución t de Student", "d": "Distribución simétrica de colas más pesadas que la normal, con ν grados de libertad. Aparece al estandarizar la media muestral usando s en vez de σ, y converge a la normal cuando ν crece.", "s": "T_ν", "l": "estadistica/09-intervalos-de-confianza"}, "hipotesis nula": {"t": "hipótesis nula", "d": "Un modelo completo de cómo se generaron los datos, lo bastante concreto para poder calcular probabilidades bajo él. Es el modelo bajo el que se calcula el valor p.", "s": "H₀", "l": "estadistica/10-pruebas-de-hipotesis"}, "valor p": {"t": "valor p", "d": "La probabilidad de un efecto al menos tan grande como el observado, calculada suponiendo la hipótesis nula cierta. No es la probabilidad de que la nula sea cierta.", "s": "", "l": "estadistica/10-pruebas-de-hipotesis"}, "estadistico de prueba": {"t": "estadístico de prueba", "d": "Una función de la muestra elegida de modo que sus valores grandes sean evidencia contra la hipótesis nula.", "s": "", "l": "estadistica/10-pruebas-de-hipotesis"}, "error de tipo i": {"t": "error de tipo I", "d": "Rechazar la hipótesis nula siendo cierta. Su probabilidad es α, y la fija el umbral elegido: no depende de n ni del tamaño del efecto.", "s": "", "l": "estadistica/10-pruebas-de-hipotesis"}, "error de tipo ii": {"t": "error de tipo II", "d": "No rechazar la hipótesis nula siendo falsa. Su probabilidad es β, y sí depende del tamaño del efecto y de n.", "s": "", "l": "estadistica/10-pruebas-de-hipotesis"}, "potencia": {"t": "potencia", "d": "La probabilidad de detectar un efecto que sí existe: 1 − β. Sube con el tamaño del efecto y con n, que entra por la raíz.", "s": "", "l": "estadistica/10-pruebas-de-hipotesis"}, "significancia estadistica": {"t": "significancia estadística", "d": "Que el valor p cae por debajo de un umbral elegido de antemano, casi siempre 0.05. Es una convención, no un resultado matemático, y no dice nada sobre el tamaño del efecto.", "s": "", "l": "estadistica/10-pruebas-de-hipotesis"}, "distribucion empirica": {"t": "distribución empírica", "d": "La distribución que pone masa 1/n en cada dato observado. Es el modelo más simple posible de la población: la propia muestra.", "s": "F̂ₙ", "l": "estadistica/11-bootstrap"}, "bootstrap": {"t": "bootstrap", "d": "Sortear n datos con reemplazo de la muestra, recalcular el estadístico y repetir B veces. Estima la anchura de la distribución muestral, no corrige su centro.", "s": "", "l": "estadistica/11-bootstrap"}, "prueba de permutacion": {"t": "prueba de permutación", "d": "Construir la distribución bajo la hipótesis nula barajando las etiquetas de grupo. Es exacta: no es una aproximación que mejore con n.", "s": "", "l": "estadistica/11-bootstrap"}, "determinante": {"t": "determinante", "d": "El factor por el que una matriz multiplica todo volumen. En 2×2 vale ad − bc, y su valor absoluto es el área del paralelogramo de sus columnas. Vale cero exactamente cuando la matriz no tiene inversa.", "s": "det(A)", "l": "matematica/08-determinante"}, "orientacion": {"t": "orientación", "d": "El sentido de giro que una transformación conserva o invierte. El signo del determinante lo dice: negativo significa que el plano se ha dado la vuelta, como en un espejo.", "s": "", "l": "matematica/08-determinante"}, "eigenvector": {"t": "eigenvector", "d": "Un vector no nulo al que la matriz no gira: Av = λv. Marca una dirección que la transformación deja quieta, solo estirada.", "s": "", "l": "matematica/09-eigenvalores"}, "eigenvalor": {"t": "eigenvalor", "d": "El factor λ por el que se estira un eigenvector. Se obtiene resolviendo det(A − λI) = 0.", "s": "λ", "l": "matematica/09-eigenvalores"}, "polinomio caracteristico": {"t": "polinomio característico", "d": "p(λ) = det(A − λI). Sus raíces son los eigenvalores. En 2×2 vale λ² − tr(A)λ + det(A).", "s": "", "l": "matematica/09-eigenvalores"}, "traza": {"t": "traza", "d": "La suma de la diagonal de una matriz cuadrada. Es también la suma de sus eigenvalores.", "s": "tr(A)", "l": "matematica/09-eigenvalores"}, "matriz simetrica": {"t": "matriz simétrica", "d": "Una matriz igual a su traspuesta. Sus eigenvalores son reales y sus eigenvectores perpendiculares, que es lo que la hace manejable.", "s": "", "l": "matematica/09-eigenvalores"}, "normal multivariante": {"t": "normal multivariante", "d": "Un vector cuya densidad lleva la forma cuadrática (x−μ)ᵀΣ⁻¹(x−μ) en el exponente. Sus curvas de nivel son elipses con ejes en los eigenvectores de Σ.", "s": "", "l": "estadistica/12-normal-multivariante"}, "matriz de covarianza": {"t": "matriz de covarianza", "d": "La matriz cuyo elemento (i,j) es Cov(xᵢ, xⱼ). Es simétrica siempre, así que sus eigenvectores son perpendiculares y sirven de ejes.", "s": "Σ", "l": "estadistica/12-normal-multivariante"}, "recta de regresion": {"t": "recta de regresión", "d": "La recta que minimiza la suma de los cuadrados de los residuos. Su pendiente es Cov(x,y)/Var(x), y pasa siempre por (x̄, ȳ).", "s": "", "l": "estadistica/13-regresion-primeros-principios"}, "residuo": {"t": "residuo", "d": "La diferencia entre un valor observado y el que predice la recta ajustada. No es el error del modelo: los errores son independientes, los residuos suman cero por construcción.", "s": "eᵢ", "l": "estadistica/13-regresion-primeros-principios"}, "coeficiente de determinacion": {"t": "coeficiente de determinación", "d": "R² = SCR/SCT, la fracción de la varianza que explica la recta. En regresión simple vale r². Mide cuánto ajusta, no si el modelo es el correcto.", "s": "R²", "l": "estadistica/13-regresion-primeros-principios"}, "regresion a la media": {"t": "regresión a la media", "d": "Que un valor extremo de x predice un valor menos extremo de y, porque la pendiente estandarizada es r < 1. Es aritmética, no un fenómeno causal.", "s": "", "l": "estadistica/13-regresion-primeros-principios"}, "mecanismo de faltantes": {"t": "mecanismo de faltantes", "d": "La regla —normalmente desconocida— que decide qué datos se observan y cuáles no. Se describe con la probabilidad de responder condicionada a los datos, y de ella depende si el análisis queda sesgado.", "s": "R", "l": "estadistica/15-datos-faltantes"}, "mcar": {"t": "MCAR", "d": "Missing completely at random: la probabilidad de que un dato falte es la misma para todos, sin depender de nada observado ni no observado. Cuesta precisión pero no sesga.", "s": "", "l": "estadistica/15-datos-faltantes"}, "mar": {"t": "MAR", "d": "Missing at random: la probabilidad de faltar depende solo de variables observadas. La media marginal queda sesgada, pero la ley de Y dado X —y con ella los coeficientes de regresión— se conserva.", "s": "", "l": "estadistica/15-datos-faltantes"}, "mnar": {"t": "MNAR", "d": "Missing not at random: la probabilidad de faltar depende del propio valor que falta, aun fijando lo observado. No se puede corregir con los datos solos: no está identificado.", "s": "", "l": "estadistica/15-datos-faltantes"}, "propension de respuesta": {"t": "propensión de respuesta", "d": "La probabilidad de que una unidad con covariables x se observe, q(x) = P(R = 1 | X = x). Reponderar por su inverso corrige el sesgo bajo MAR, siempre que sea positiva para todo x.", "s": "q(x)", "l": "estadistica/15-datos-faltantes"}, "analisis de casos completos": {"t": "análisis de casos completos", "d": "Analizar solo las filas sin huecos, descartando el resto. Es insesgado si el hecho de responder no covaría con lo que se mide, y solo en ese caso.", "s": "", "l": "estadistica/15-datos-faltantes"}, "imputacion": {"t": "imputación", "d": "Rellenar cada hueco con un valor estimado para poder analizar la tabla completa. Conserva la media si se rellena con ella, pero encoge la varianza y estrecha los intervalos.", "s": "", "l": "estadistica/15-datos-faltantes"}, "imputacion multiple": {"t": "imputación múltiple", "d": "Imputar varias veces con ruido, analizar cada versión y combinar los resultados sumando la variabilidad entre imputaciones a la de dentro de cada una. Es la forma de imputar sin mentir sobre la incertidumbre.", "s": "", "l": "estadistica/15-datos-faltantes"}, "post-estratificacion": {"t": "post-estratificación", "d": "Partir la muestra en estratos según una variable observada, promediar dentro de cada uno con los casos completos y recombinar con el peso real de cada estrato. Aproxima la reponderación por la propensión.", "s": "", "l": "estadistica/15-datos-faltantes"}, "identificabilidad": {"t": "identificabilidad", "d": "Que dos poblaciones distintas no puedan producir la misma distribución de datos observados. Si un parámetro no está identificado, ningún método ni ninguna cantidad de datos lo determina: hace falta un supuesto.", "s": "", "l": "estadistica/15-datos-faltantes"}, "calibracion": {"t": "calibración", "d": "Que un pronóstico probabilístico diga la verdad sobre el nivel: entre los casos en que anunció p, la frecuencia real fue p. Se comprueba por grupos de casos, nunca sobre uno solo.", "s": "", "l": "estadistica/16-calibracion"}, "score de brier": {"t": "score de Brier", "d": "El error cuadrático medio de un pronóstico contra el resultado 0/1: E[(p̂ − Y)²]. Es una regla propia: se minimiza anunciando la probabilidad verdadera.", "s": "BS", "l": "estadistica/16-calibracion"}, "resolucion de un pronostico": {"t": "resolución de un pronóstico", "d": "Cuánto separa el pronóstico unos casos de otros, medido como la dispersión de las frecuencias reales de sus grupos respecto de la tasa base. Entra restando en el Brier: más resolución, mejor.", "s": "", "l": "estadistica/16-calibracion"}, "curva de ganancia": {"t": "curva de ganancia", "d": "La fracción de todos los positivos que cae dentro del u por ciento de casos con mayor pronóstico. Depende solo del orden, no del nivel anunciado.", "s": "G(u)", "l": "estadistica/16-calibracion"}, "lift": {"t": "lift", "d": "La ganancia dividida entre la fracción elegida, G(u)/u: cuántas veces más positivos que eligiendo al azar. Su techo es min(1/u, 1/tasa base).", "s": "L(u)", "l": "estadistica/16-calibracion"}, "regresion isotonica": {"t": "regresión isotónica", "d": "Ajustar una función creciente por tramos a los datos fundiendo los bloques que violan la monotonía (PAVA). Recalibra un pronóstico sin cambiar el orden de los casos.", "s": "", "l": "estadistica/16-calibracion"}, "tasa base": {"t": "tasa base", "d": "La proporción de positivos en la población, E[Y]. Fija la incertidumbre del problema y el techo del lift, y no depende de ningún modelo.", "s": "ȳ", "l": "estadistica/16-calibracion"}, "tasa de error por familia": {"t": "tasa de error por familia", "d": "La probabilidad de cometer al menos un error de tipo I en toda una familia de pruebas. Es lo que controlan Bonferroni y Holm.", "s": "FWER", "l": "estadistica/17-p-hacking"}, "tasa de falsos descubrimientos": {"t": "tasa de falsos descubrimientos", "d": "La proporción esperada de hallazgos falsos entre los declarados. Es una promesa distinta —y más débil— que la tasa de error por familia, y la que controla Benjamini-Hochberg.", "s": "FDR", "l": "estadistica/17-p-hacking"}, "correccion de bonferroni": {"t": "corrección de Bonferroni", "d": "Exigir p ≤ α/m en cada una de las m pruebas. Controla la tasa de error por familia sin suponer independencia, por la desigualdad de Boole, y es conservadora si las pruebas están correlacionadas.", "s": "", "l": "estadistica/17-p-hacking"}, "metodo de holm": {"t": "método de Holm", "d": "Recorrer los valores p ordenados rechazando mientras p₍ᵢ₎ ≤ α/(m−i+1). Da la misma garantía que Bonferroni y rechaza siempre al menos tanto, así que lo domina.", "s": "", "l": "estadistica/17-p-hacking"}, "procedimiento de benjamini-hochberg": {"t": "procedimiento de Benjamini-Hochberg", "d": "Rechazar las k hipótesis con menores valores p, donde k es el mayor índice con p₍ᵢ₎ ≤ αi/m. Controla la tasa de falsos descubrimientos, no la de error por familia.", "s": "", "l": "estadistica/17-p-hacking"}, "p-hacking": {"t": "p-hacking", "d": "Reportar el mejor de varios análisis como si hubiera sido el único. El valor p que se publica ya no es uniforme bajo H₀ sino el mínimo de m, y por eso el umbral del 5 % deja de significar 5 %.", "s": "", "l": "estadistica/17-p-hacking"}, "producto interno": {"t": "producto interno", "d": "La suma de los productos componente a componente de dos vectores, ⟨u,v⟩ = uᵀv. Es la operación que le da al espacio longitud, distancia y ángulo.", "s": "⟨u,v⟩", "l": "matematica/04-producto-interno"}, "norma": {"t": "norma", "d": "La longitud de un vector, ‖u‖ = √⟨u,u⟩. Existe porque el producto interno es definido positivo: ⟨u,u⟩ nunca es negativo.", "s": "‖u‖", "l": "matematica/04-producto-interno"}, "ortogonalidad": {"t": "ortogonalidad", "d": "Dos vectores son ortogonales cuando su producto interno vale cero. Es una condición algebraica, y equivale a que el ángulo entre ellos sea recto.", "s": "u ⊥ v", "l": "matematica/04-producto-interno"}, "angulo entre vectores": {"t": "ángulo entre vectores", "d": "El único θ en [0, π] con cos θ = ⟨u,v⟩ / (‖u‖‖v‖). Está bien definido gracias a Cauchy-Schwarz, que garantiza que ese cociente no se sale de [−1,1].", "s": "θ", "l": "matematica/04-producto-interno"}, "desigualdad de cauchy-schwarz": {"t": "desigualdad de Cauchy-Schwarz", "d": "|⟨u,v⟩| ≤ ‖u‖‖v‖, con igualdad solo si uno de los vectores es múltiplo del otro. Es lo que hace existir al ángulo y lo que acota la correlación entre −1 y 1.", "s": "", "l": "matematica/04-producto-interno"}, "desigualdad triangular": {"t": "desigualdad triangular", "d": "‖u+v‖ ≤ ‖u‖ + ‖v‖: ir en línea recta nunca es más largo que dar un rodeo. La igualdad exige que uno sea múltiplo no negativo del otro.", "s": "", "l": "matematica/04-producto-interno"}, "proyeccion ortogonal": {"t": "proyección ortogonal", "d": "La sombra de un vector sobre un subespacio: el único punto del subespacio cuyo residuo es perpendicular a él. Es también el punto más cercano, por Pitágoras.", "s": "", "l": "matematica/05-proyeccion-ortogonal"}, "matriz de proyeccion": {"t": "matriz de proyección", "d": "La matriz P tal que Pb es la proyección de b. Es simétrica e idempotente (P² = P), sus eigenvalores son ceros y unos, y su traza es la dimensión del subespacio.", "s": "P", "l": "matematica/05-proyeccion-ortogonal"}, "ecuaciones normales": {"t": "ecuaciones normales", "d": "AᵀA x̂ = Aᵀb, el sistema que resuelve la proyección sobre el espacio columna de A. Sale de exigir que el residuo sea ortogonal a todas las columnas.", "s": "", "l": "matematica/05-proyeccion-ortogonal"}, "minimos cuadrados": {"t": "mínimos cuadrados", "d": "Encontrar los coeficientes que minimizan la suma de cuadrados de los residuos, ‖b − Ax‖². Su solución es la proyección de b sobre el espacio columna de A.", "s": "", "l": "matematica/06-minimos-cuadrados"}, "matriz sombrero": {"t": "matriz sombrero", "d": "H = A(AᵀA)⁻¹Aᵀ, la que convierte y en ŷ. Es la matriz de proyección sobre el espacio columna; su traza son los grados de libertad del modelo y su diagonal, el leverage de cada observación.", "s": "H", "l": "matematica/06-minimos-cuadrados"}, "leverage": {"t": "leverage", "d": "El elemento hᵢᵢ de la diagonal de la matriz sombrero: cuánto influye una observación sobre su propia predicción. Depende de dónde están los predictores, no del valor observado.", "s": "hᵢᵢ", "l": "matematica/06-minimos-cuadrados"}, "espacio columna": {"t": "espacio columna", "d": "El conjunto de todos los Ax posibles, que es el span de las columnas de A. Es todo lo que la matriz puede producir: su alcance.", "s": "col(A)", "l": "matematica/03-espacio-columna"}, "rango": {"t": "rango", "d": "La dimensión del espacio columna: cuántas direcciones independientes hay entre las columnas. Es rango columna completo cuando iguala al número de columnas.", "s": "", "l": "matematica/03-espacio-columna"}, "nucleo": {"t": "núcleo", "d": "El conjunto de vectores que la matriz manda al cero, {x : Ax = 0}. Es un subespacio, y su dimensión mide cuánta información aniquila la matriz.", "s": "ker(A)", "l": "matematica/03-espacio-columna"}, "teorema del rango-nulidad": {"t": "teorema del rango-nulidad", "d": "rango(A) + dim ker(A) = n, con n el número de columnas. Lo que gana el núcleo lo pierde el rango, en cantidades exactamente complementarias.", "s": "", "l": "matematica/03-espacio-columna"}, "colinealidad": {"t": "colinealidad", "d": "Que una columna de la matriz de diseño sea combinación lineal de otras. Baja el rango, hace infinitas las soluciones y vuelve inidentificables los coeficientes.", "s": "", "l": "matematica/03-espacio-columna"}, "combinacion lineal": {"t": "combinación lineal", "d": "Una suma de vectores multiplicados por escalares: a₁v₁ + … + aₙvₙ. Es la única expresión que permiten formar las dos operaciones de un espacio vectorial, y de ella salen el span, el rango y el producto matriz-vector.", "s": "", "l": "matematica/01-vectores-y-espacios"}, "transformacion lineal": {"t": "transformación lineal", "d": "Una función entre espacios vectoriales que respeta sumas y múltiplos: T(u+v) = T(u)+T(v) y T(αu) = αT(u). Toda matriz es una, y toda una tiene matriz.", "s": "T", "l": "matematica/02-matriz-como-transformacion"}, "espacio vectorial": {"t": "espacio vectorial", "d": "Un conjunto donde se puede sumar y escalar respetando ocho condiciones. Los vectores de Rⁿ, las funciones y los polinomios lo son, y todo lo que se demuestre para uno vale para los demás.", "s": "", "l": "matematica/01-vectores-y-espacios"}, "span": {"t": "span", "d": "El conjunto de todas las combinaciones lineales de unos vectores dados. Es siempre un espacio vectorial, y en el plano es un punto, una recta o todo R².", "s": "", "l": "matematica/01-vectores-y-espacios"}, "independencia lineal": {"t": "independencia lineal", "d": "Que la única combinación lineal de unos vectores que da el cero sea la de todos los coeficientes nulos. Si no lo son, alguno sobra: se escribe con los demás.", "s": "", "l": "matematica/01-vectores-y-espacios"}, "base": {"t": "base", "d": "Una familia linealmente independiente cuyo span es todo el espacio. Su tamaño es la dimensión, y en ella las coordenadas de cada vector son únicas.", "s": "", "l": "matematica/01-vectores-y-espacios"}, "base ortonormal": {"t": "base ortonormal", "d": "Una base de vectores perpendiculares entre sí y de norma 1, es decir QᵀQ = I. En ella la proyección se calcula con productos internos, sin resolver ningún sistema.", "s": "", "l": "matematica/07-gram-schmidt-qr"}, "gram-schmidt": {"t": "Gram-Schmidt", "d": "El proceso que convierte una familia independiente en una ortonormal: a cada vector se le quitan sus sombras sobre los anteriores y se normaliza lo que queda.", "s": "", "l": "matematica/07-gram-schmidt-qr"}, "factorizacion qr": {"t": "factorización QR", "d": "Escribir A = QR con Q de columnas ortonormales y R triangular superior. Resuelve mínimos cuadrados sin formar AᵀA, trabajando con el condicionamiento de A y no con su cuadrado.", "s": "", "l": "matematica/07-gram-schmidt-qr"}, "perdida de ortogonalidad": {"t": "pérdida de ortogonalidad", "d": "Que las columnas que deberían ser perpendiculares dejen de serlo por el redondeo de punto flotante. Crece con el condicionamiento y distingue al Gram-Schmidt clásico del modificado.", "s": "", "l": "matematica/07-gram-schmidt-qr"}, "probabilidad condicional": {"t": "probabilidad condicional", "d": "P(A|B) = P(A∩B)/P(B): de todo el espacio en que B ocurre, qué fracción tiene también A. Exige P(B) > 0.", "s": "P(A|B)", "l": "estadistica/18-teorema-de-bayes"}, "teorema de bayes": {"t": "teorema de Bayes", "d": "P(H|D) = P(D|H)·P(H)/P(D). Invierte el condicionamiento —de «qué datos son probables dada la hipótesis» a «qué hipótesis es probable dados los datos»— a cambio de exigir un prior.", "s": "", "l": "estadistica/18-teorema-de-bayes"}, "ley de probabilidad total": {"t": "ley de probabilidad total", "d": "P(D) = Σ P(D|Hᵢ)P(Hᵢ) sobre una lista exhaustiva y excluyente de hipótesis. Es lo que permite calcular el denominador de Bayes sumando una columna.", "s": "", "l": "estadistica/18-teorema-de-bayes"}, "prior": {"t": "prior", "d": "La distribución de creencia sobre las hipótesis antes de ver los datos. Sin él no se puede invertir el condicionamiento: es el precio que cobra el teorema de Bayes.", "s": "P(H)", "l": "estadistica/18-teorema-de-bayes"}, "posterior": {"t": "posterior", "d": "La distribución de creencia sobre las hipótesis después de ver los datos, proporcional al prior por la verosimilitud.", "s": "P(H|D)", "l": "estadistica/18-teorema-de-bayes"}, "tabla bayesiana": {"t": "tabla bayesiana", "d": "Una fila por hipótesis y cuatro columnas: prior, verosimilitud, su producto y el posterior. La suma de la columna del producto es la evidencia.", "s": "", "l": "estadistica/18-teorema-de-bayes"}, "factor de bayes": {"t": "factor de Bayes", "d": "El cociente de verosimilitudes P(D|H)/P(D|¬H): cuánta evidencia trae un dato, con independencia del prior. Multiplica la razón previa para dar la posterior.", "s": "", "l": "estadistica/18-teorema-de-bayes"}, "diagonalizable": {"t": "diagonalizable", "d": "Una matriz es diagonalizable si se escribe A = P D P⁻¹ con D diagonal, lo que ocurre exactamente cuando tiene n eigenvectores independientes. En su propia base solo estira ejes.", "s": "", "l": "matematica/10-diagonalizacion"}, "potencia iterada": {"t": "potencia iterada", "d": "Multiplicar un vector por la matriz y renormalizar, una y otra vez. Converge a la dirección del eigenvector dominante, con error que cae como |λ₂/λ₁|^k.", "s": "", "l": "matematica/10-diagonalizacion"}, "descomposicion en valores singulares": {"t": "descomposición en valores singulares", "d": "A = U Σ Vᵀ con U y V ortogonales y Σ diagonal no negativa. La tiene toda matriz, sea o no cuadrada: rota, estira cada eje y vuelve a rotar.", "s": "SVD", "l": "matematica/11-svd"}, "valores singulares": {"t": "valores singulares", "d": "Las entradas diagonales de Σ, que son las raíces de los eigenvalores de AᵀA. Miden cuánto estira la matriz en cada dirección principal; su número no nulo es el rango.", "s": "σᵢ", "l": "matematica/11-svd"}, "numero de condicion": {"t": "número de condición", "d": "El cociente entre el mayor y el menor eigenvalor de una matriz definida positiva. Decide la velocidad del descenso de gradiente: la mejor tasa posible es (κ−1)/(κ+1).", "s": "κ", "l": "matematica/16-descenso-de-gradiente"}, "forma cuadratica": {"t": "forma cuadrática", "d": "La función q(x) = xᵀAx. En la base propia es una suma de cuadrados con pesos los eigenvalores, y de ahí sale todo: su signo, sus extremos y sus curvas de nivel.", "s": "", "l": "matematica/12-formas-cuadraticas"}, "definida positiva": {"t": "definida positiva", "d": "Una matriz simétrica con xᵀAx > 0 para todo x ≠ 0, lo que equivale a que todos sus eigenvalores sean positivos. Sus curvas de nivel son elipses.", "s": "A ≻ 0", "l": "matematica/12-formas-cuadraticas"}, "factorizacion de cholesky": {"t": "factorización de Cholesky", "d": "A = LLᵀ con L triangular inferior de diagonal positiva. Existe exactamente cuando A es definida positiva, así que intentarla es la forma barata de comprobarlo.", "s": "", "l": "matematica/12-formas-cuadraticas"}, "nucleo de una densidad": {"t": "núcleo de una densidad", "d": "La densidad sin su constante de normalización: cualquier g con f = c·g y c independiente del parámetro. Reconocer el núcleo basta para identificar el posterior, porque dos densidades proporcionales son iguales.", "s": "∝", "l": "estadistica/19-priors-conjugados"}, "evidencia": {"t": "evidencia", "d": "La verosimilitud marginal m(x) = ∫p(x|θ)π(θ)dθ, el denominador del teorema de Bayes. No depende del parámetro, así que con priors conjugados no hace falta calcularla.", "s": "m(x)", "l": "estadistica/19-priors-conjugados"}, "prior conjugado": {"t": "prior conjugado", "d": "Un prior tal que el posterior cae en la misma familia. Es propiedad del par prior-verosimilitud: la Beta es conjugada frente a una binomial y no frente a una normal.", "s": "π(θ)", "l": "estadistica/19-priors-conjugados"}, "distribucion beta": {"t": "distribución Beta", "d": "La distribución sobre (0,1) con densidad proporcional a θ^(a−1)(1−θ)^(b−1) y media a/(a+b). Es el prior conjugado de la verosimilitud binomial.", "s": "Beta(a,b)", "l": "estadistica/19-priors-conjugados"}, "distribucion gamma": {"t": "distribución Gamma", "d": "La distribución sobre (0,∞) con densidad proporcional a λ^(a−1)e^(−bλ), forma a y tasa b, de media a/b. Es el prior conjugado de la verosimilitud de Poisson.", "s": "Gamma(a,b)", "l": "estadistica/19-priors-conjugados"}, "pseudoconteo": {"t": "pseudoconteo", "d": "La lectura de los parámetros de un prior conjugado como datos ficticios ya observados: en una Beta(a,b), a éxitos y b fracasos, con a+b como tamaño de esa muestra imaginaria.", "s": "a+b", "l": "estadistica/19-priors-conjugados"}, "precision": {"t": "precisión", "d": "El inverso de la varianza, τ = 1/σ². Se usa porque al actualizar una normal las precisiones se suman, mientras que las varianzas no hacen nada simple.", "s": "τ", "l": "estadistica/19-priors-conjugados"}, "verosimilitud marginal": {"t": "verosimilitud marginal", "d": "La probabilidad de los datos promediada sobre el prior, m(x) = ∫p(x|θ)π(θ)dθ. Actualiza los pesos de una mezcla de priors y es con lo que se comparan modelos enteros.", "s": "m(x)", "l": "estadistica/19-priors-conjugados"}, "distribucion predictiva": {"t": "distribución predictiva", "d": "La distribución del próximo dato, obtenida integrando la verosimilitud contra el posterior. Vive en el espacio de los datos, no en el del parámetro.", "s": "p(x̃|x)", "l": "estadistica/20-distribuciones-predictivas"}, "mezcla de distribuciones": {"t": "mezcla de distribuciones", "d": "Una distribución formada promediando otras con pesos que suman uno. Toda predictiva es una mezcla de las distribuciones de muestreo, pesadas por el posterior.", "s": "Σ wⱼ pⱼ", "l": "estadistica/20-distribuciones-predictivas"}, "distribucion beta-binomial": {"t": "distribución Beta-binomial", "d": "La predictiva de ñ ensayos bajo un posterior Beta(a,b). Tiene la misma media que la binomial de enchufe y varianza mayor en razón (a+b+ñ)/(a+b+1).", "s": "BetaBin(ñ,a,b)", "l": "estadistica/20-distribuciones-predictivas"}, "distribucion binomial negativa": {"t": "distribución binomial negativa", "d": "La predictiva de un conteo bajo un posterior Gamma. Aparece siempre que se promedian Poissons con media incierta, y por eso los conteos reales suelen estar sobredispersos.", "s": "BinNeg(a,p)", "l": "estadistica/20-distribuciones-predictivas"}, "estimador de enchufe": {"t": "estimador de enchufe", "d": "Estimar el parámetro y después tratarlo como si fuera el valor verdadero. Ignora el término Var(E[x̃|θ]) de la varianza total, y por eso sus intervalos cubren menos de lo que prometen.", "s": "p(·|θ̂)", "l": "estadistica/20-distribuciones-predictivas"}, "sobredispersion": {"t": "sobredispersión", "d": "Que un conteo tenga más varianza que la que su modelo predice. Una mezcla de Poissons siempre está sobredispersa respecto de la Poisson con la misma media.", "s": "Var > E", "l": "estadistica/20-distribuciones-predictivas"}, "navaja de occam bayesiana": {"t": "navaja de Occam bayesiana", "d": "Que un modelo más flexible sea penalizado sin añadir nada: su predictiva previa reparte una unidad de masa entre más conjuntos de datos posibles, así que le toca menos al que de verdad ocurrió.", "s": "Σₓ m(x) = 1", "l": "estadistica/21-comparacion-de-modelos"}, "puntuacion logaritmica": {"t": "puntuación logarítmica", "d": "La suma de los logaritmos de las probabilidades que un pronosticador asignó a lo que ocurrió. La verosimilitud marginal es exactamente eso, pronosticando cada dato con los anteriores.", "s": "Σ log p", "l": "estadistica/21-comparacion-de-modelos"}, "cadena de markov": {"t": "cadena de Markov", "d": "Una sucesión aleatoria en la que el siguiente estado depende del pasado solo a través del actual. Lo que la hace útil aquí es que se puede diseñar para que su distribución de equilibrio sea el posterior.", "s": "P(x,y)", "l": "estadistica/22-metropolis-hastings"}, "distribucion estacionaria": {"t": "distribución estacionaria", "d": "La distribución que la cadena deja invariante: si se arranca en ella, se sigue en ella. El objetivo de MCMC es construir una cadena cuya estacionaria sea el posterior.", "s": "πP = π", "l": "estadistica/22-metropolis-hastings"}, "balance detallado": {"t": "balance detallado", "d": "Que en equilibrio pase tanta masa de x a y como de y a x: π(x)P(x,y) = π(y)P(y,x). Es condición suficiente de estacionariedad, y se comprueba mirando pares de estados.", "s": "π(x)P(x,y)", "l": "estadistica/22-metropolis-hastings"}, "metropolis-hastings": {"t": "Metropolis-Hastings", "d": "El algoritmo que propone un salto y lo acepta con probabilidad min(1, π̃(y)q(x|y)/π̃(x)q(y|x)). Solo usa cocientes del objetivo, así que no necesita su constante de normalización.", "s": "α(x,y)", "l": "estadistica/22-metropolis-hastings"}, "autocorrelacion": {"t": "autocorrelación", "d": "La correlación de una serie consigo misma a un retardo dado. En una cadena MCMC es lo que hace que n iteraciones valgan menos que n muestras independientes.", "s": "ρₖ", "l": "estadistica/22-metropolis-hastings"}, "tamano de muestra efectivo": {"t": "tamaño de muestra efectivo", "d": "n/τ con τ = 1 + 2Σρₖ: cuántas muestras independientes darían la misma precisión que la cadena. Un τ de 150 significa una muestra útil por cada 150 iteraciones.", "s": "n_ef", "l": "estadistica/22-metropolis-hastings"}, "tasa de aceptacion": {"t": "tasa de aceptación", "d": "La fracción de propuestas aceptadas. Cerca de uno indica un paso demasiado corto y cerca de cero uno demasiado largo; en una dimensión el óptimo ronda 0,44.", "s": "α̂", "l": "estadistica/22-metropolis-hastings"}, "condicional completa": {"t": "condicional completa", "d": "La distribución de un bloque de parámetros dados todos los demás y los datos. Se obtiene tachando del posterior conjunto todo lo que no contiene ese bloque.", "s": "π(θⱼ|θ₋ⱼ,x)", "l": "estadistica/23-gibbs-sampling"}, "gibbs sampling": {"t": "Gibbs sampling", "d": "Recorrer los bloques de parámetros sorteando cada uno de su condicional completa. Es Metropolis-Hastings con aceptación uno: no hay nada que rechazar ni que ajustar.", "s": "—", "l": "estadistica/23-gibbs-sampling"}, "inversa-gamma": {"t": "inversa-gamma", "d": "La distribución de 1/G cuando G es Gamma. Es la condicional completa de una varianza con prior 1/σ², y por eso aparece en todo modelo normal con varianza desconocida.", "s": "IG(α,β)", "l": "estadistica/23-gibbs-sampling"}, "reparametrizacion": {"t": "reparametrización", "d": "Cambiar las coordenadas en que se muestrea para quitar la correlación entre parámetros. Rotar a los ejes principales lleva el factor de ineficiencia de Gibbs de cien a uno.", "s": "—", "l": "estadistica/23-gibbs-sampling"}, "r de gelman-rubin": {"t": "R de Gelman-Rubin", "d": "El diagnóstico R̂ = √(V̂/W), que compara la dispersión entre las medias de varias cadenas con la dispersión dentro de cada una. Con cadenas estacionarias vale aproximadamente √(1+(τ−1)/n), no uno.", "s": "R̂", "l": "estadistica/24-diagnostico-de-cadenas"}, "error de monte carlo": {"t": "error de Monte Carlo", "d": "σ/√n_ef: el error estándar de un resumen calculado sobre una cadena. Decide cuántas cifras de un resultado son defendibles.", "s": "EMC", "l": "estadistica/24-diagnostico-de-cadenas"}, "quema": {"t": "quema", "d": "Los primeros estados de una cadena, que todavía recuerdan el punto de arranque y se descartan antes de resumir nada.", "s": "—", "l": "estadistica/24-diagnostico-de-cadenas"}, "derivada": {"t": "derivada", "d": "La tasa de cambio instantánea de una función en un punto: el límite del cociente de incrementos [f(a+h)−f(a)]/h cuando h tiende a cero.", "s": "f'(a)", "l": "matematica/13-derivada-gradiente"}, "regla de la cadena": {"t": "regla de la cadena", "d": "La derivada de una composición de funciones es el producto de las derivadas: (f∘g)'(a) = f'(g(a))·g'(a).", "s": "", "l": "matematica/13-derivada-gradiente"}, "derivada parcial": {"t": "derivada parcial", "d": "La derivada de una función de varias variables respecto a una sola de ellas, con las demás fijas.", "s": "∂f/∂xᵢ", "l": "matematica/13-derivada-gradiente"}, "derivada direccional": {"t": "derivada direccional", "d": "La tasa de cambio de una función en un punto, medida en una dirección unitaria concreta. La derivada parcial es el caso particular en la dirección de un vector de la base canónica.", "s": "D_vf(a)", "l": "matematica/13-derivada-gradiente"}, "gradiente": {"t": "gradiente", "d": "El vector de las derivadas parciales de una función. Para una función diferenciable, apunta en la dirección de máximo crecimiento y su norma es la tasa de ese crecimiento.", "s": "∇f(a)", "l": "matematica/13-derivada-gradiente"}, "diferenciable": {"t": "diferenciable", "d": "Una función es diferenciable en un punto si ahí admite una aproximación lineal cuyo error se hace despreciable frente a la distancia al punto.", "s": "", "l": "matematica/13-derivada-gradiente"}, "hessiana": {"t": "hessiana", "d": "La matriz de todas las segundas derivadas parciales de una función. Es simétrica cuando esas parciales son continuas, y sus eigenvalores clasifican los puntos críticos.", "s": "∇²f", "l": "matematica/14-hessiana-taylor"}, "polinomio de taylor": {"t": "polinomio de Taylor", "d": "La aproximación polinómica de una función alrededor de un punto. El de orden dos añade a la recta tangente el término de curvatura ½hᵀ∇²f h.", "s": "", "l": "matematica/14-hessiana-taylor"}, "punto critico": {"t": "punto crítico", "d": "Un punto donde el gradiente se anula. Todo máximo o mínimo local de una función diferenciable lo es, pero no al revés.", "s": "", "l": "matematica/14-hessiana-taylor"}, "punto silla": {"t": "punto silla", "d": "Un punto crítico que no es ni máximo ni mínimo: en unas direcciones la función sube y en otras baja. Aparece cuando la hessiana es indefinida.", "s": "", "l": "matematica/14-hessiana-taylor"}, "conjunto convexo": {"t": "conjunto convexo", "d": "Un conjunto donde el segmento que une dos puntos cualesquiera se queda dentro.", "s": "", "l": "matematica/15-convexidad"}, "funcion convexa": {"t": "función convexa", "d": "Una función cuya gráfica queda por debajo de todas sus cuerdas: f(tx+(1−t)y) ≤ t f(x) + (1−t) f(y). Equivale a tener la hessiana semidefinida positiva.", "s": "", "l": "matematica/15-convexidad"}, "estrictamente convexa": {"t": "estrictamente convexa", "d": "Una función convexa cuya desigualdad es estricta fuera de los extremos. Garantiza que el minimizador, si existe, es único.", "s": "", "l": "matematica/15-convexidad"}, "minimo global": {"t": "mínimo global", "d": "Un punto donde la función vale menos o igual que en todo el dominio, no solo en un entorno. En una función convexa todo mínimo local lo es.", "s": "", "l": "matematica/15-convexidad"}, "descenso de gradiente": {"t": "descenso de gradiente", "d": "El método que avanza en contra del gradiente: x_{k+1} = x_k − η∇f(x_k). Con paso suficientemente corto la función baja en cada iteración.", "s": "η", "l": "matematica/16-descenso-de-gradiente"}, "gradiente lipschitz": {"t": "gradiente Lipschitz", "d": "Un gradiente que no puede cambiar más rápido que L veces la distancia: ‖∇f(y)−∇f(x)‖ ≤ L‖y−x‖. Para una cuadrática, la menor L válida es el mayor eigenvalor.", "s": "L", "l": "matematica/16-descenso-de-gradiente"}, "lema de descenso": {"t": "lema de descenso", "d": "La cota f(y) ≤ f(x) + ∇f(x)·(y−x) + (L/2)‖y−x‖². Convierte «la función baja» en una cantidad medible por iteración.", "s": "", "l": "matematica/16-descenso-de-gradiente"}, "metodo de newton": {"t": "método de Newton", "d": "El método que en cada paso minimiza el modelo cuadrático de Taylor: x_{k+1} = x_k − H⁻¹∇f. En una cuadrática acierta de un solo salto.", "s": "", "l": "matematica/17-metodo-de-newton"}, "convergencia cuadratica": {"t": "convergencia cuadrática", "d": "Una sucesión donde el error nuevo es proporcional al cuadrado del anterior: ‖e_{k+1}‖ ≤ C‖e_k‖². El número de dígitos correctos se duplica en cada paso.", "s": "", "l": "matematica/17-metodo-de-newton"}, "newton regularizado": {"t": "Newton regularizado", "d": "La variante que usa H + μI en lugar de H, con μ el menor valor que la vuelve definida positiva, y recorta el paso hasta que la función baje.", "s": "", "l": "matematica/17-metodo-de-newton"}, "multiplicador de lagrange": {"t": "multiplicador de Lagrange", "d": "El escalar λ que mide cuánto hay que inclinar el gradiente del objetivo para alinearlo con el de la restricción. Cuantifica cuánto aprieta esa restricción.", "s": "λ", "l": "matematica/18-lagrange-kkt"}, "lagrangiano": {"t": "lagrangiano", "d": "La función L(x,λ) = f(x) − λg(x). Sus puntos críticos reproducen a la vez la condición de Lagrange y la restricción, convirtiendo un problema con restricciones en uno sin ellas.", "s": "", "l": "matematica/18-lagrange-kkt"}, "condiciones kkt": {"t": "condiciones KKT", "d": "Las cuatro condiciones de Karush-Kuhn-Tucker: estacionariedad, factibilidad, multiplicadores no negativos y holgura complementaria. En un problema convexo certifican el óptimo global.", "s": "", "l": "matematica/18-lagrange-kkt"}, "holgura complementaria": {"t": "holgura complementaria", "d": "La condición λᵢgᵢ(x*) = 0: para cada restricción de desigualdad, o está activa, o su multiplicador es cero. Una restricción que no aprieta no influye.", "s": "", "l": "matematica/18-lagrange-kkt"}, "objeto": {"t": "objeto", "d": "Todo dato de Python. Queda caracterizado por su identidad (constante), su tipo (constante) y su valor, que según el tipo puede cambiar o no.", "s": "", "l": "python/01-tipos-y-estructuras"}, "identidad": {"t": "identidad", "d": "El entero que distingue a un objeto de cualquier otro vivo, fijado al crearlo y constante durante toda su vida. Lo devuelve id() y lo compara el operador is.", "s": "", "l": "python/01-tipos-y-estructuras"}, "alias": {"t": "alias", "d": "Dos nombres vinculados al mismo objeto. Se produce con una simple asignación, porque asignar no copia, y hace que toda mutación hecha por uno la vea el otro.", "s": "", "l": "python/01-tipos-y-estructuras"}, "mutable": {"t": "mutable", "d": "Un tipo que admite operaciones que cambian el valor de un objeto conservando su identidad. Son mutables list, dict, set y bytearray.", "s": "", "l": "python/01-tipos-y-estructuras"}, "inmutable": {"t": "inmutable", "d": "Un tipo en el que ninguna operación cambia el valor conservando la identidad: para cambiar hay que construir un objeto nuevo. Son inmutables int, float, str, tuple y frozenset.", "s": "", "l": "python/01-tipos-y-estructuras"}, "copia superficial": {"t": "copia superficial", "d": "Una colección nueva cuyos elementos son los mismos objetos que los del original. Aísla la colección externa y nada más. La producen x[:], x.copy(), list(x) y copy.copy(x).", "s": "", "l": "python/01-tipos-y-estructuras"}, "copia profunda": {"t": "copia profunda", "d": "Una colección nueva cuyos elementos son a su vez copias profundas, de modo que ningún objeto alcanzable desde la copia lo es desde el original. La produce copy.deepcopy(x).", "s": "", "l": "python/01-tipos-y-estructuras"}, "hashable": {"t": "hashable", "d": "Un objeto con hash constante durante su vida y compatible con la igualdad: si a == b entonces hash(a) == hash(b). Es lo que un diccionario o un conjunto exigen a sus claves.", "s": "", "l": "python/01-tipos-y-estructuras"}, "tabla hash": {"t": "tabla hash", "d": "La estructura que sostiene a dict y set: coloca cada clave en un cubo determinado por su hash y dentro del cubo la localiza comparando con ==. De ahí que la pertenencia cueste O(1) esperado.", "s": "", "l": "python/01-tipos-y-estructuras"}, "coste amortizado": {"t": "coste amortizado", "d": "El coste medio por operación a lo largo de una serie larga, aunque alguna operación suelta sea cara. append es O(1) amortizado: reubica pocas veces y cada reubicación paga por las siguientes.", "s": "", "l": "python/01-tipos-y-estructuras"}, "lista": {"t": "lista", "d": "Colección ordenada y mutable que admite repetidos, escrita [a, b, c]. Indexa en O(1) y busca por valor en O(n).", "s": "", "l": "python/01-tipos-y-estructuras"}, "tupla": {"t": "tupla", "d": "Colección ordenada e inmutable que admite repetidos, escrita (a, b, c). Al ser inmutable es hashable, y por eso sirve de clave de un diccionario.", "s": "", "l": "python/01-tipos-y-estructuras"}, "conjunto": {"t": "conjunto", "d": "Colección sin repetidos y sin orden de magnitud, escrita {a, b, c}. Sus elementos han de ser hashables, y a cambio la pertenencia cuesta O(1) esperado.", "s": "", "l": "python/01-tipos-y-estructuras"}, "diccionario": {"t": "diccionario", "d": "Colección de pares clave a valor, escrita {k: v}. Las claves han de ser hashables y únicas; conserva el orden de inserción desde Python 3.7.", "s": "", "l": "python/01-tipos-y-estructuras"}, "legb": {"t": "legb", "d": "El orden en que Python resuelve un nombre dentro de una función: Local, Envolvente, Global, Integrado. Se detiene en el primer ámbito que lo vincule, y si ninguno lo hace lanza NameError.", "s": "", "l": "python/02-funciones-y-scope"}, "ambito": {"t": "ámbito", "d": "Una tabla de vínculos entre nombres y objetos. Cada llamada a una función abre el suyo, y un bucle no abre ninguno.", "s": "", "l": "python/02-funciones-y-scope"}, "argumento": {"t": "argumento", "d": "El objeto que se pasa en una llamada concreta. Se empareja con un parámetro por posición o por nombre.", "s": "", "l": "python/02-funciones-y-scope"}, "valor por defecto": {"t": "valor por defecto", "d": "La expresión escrita como p=expr en la firma. Se evalúa una sola vez, al ejecutar el def, y el objeto resultante queda en f.__defaults__ y se comparte entre todas las llamadas que omitan ese argumento.", "s": "", "l": "python/02-funciones-y-scope"}, "cierre": {"t": "cierre", "d": "Una función anidada junto con las celdas que captura de un ámbito que la contiene. Lee el contenido de la celda en el instante de la llamada, no en el de la definición.", "s": "", "l": "python/02-funciones-y-scope"}, "celda": {"t": "celda", "d": "El contenedor compartido donde vive un nombre capturado por una función anidada. Sobrevive al retorno de la función externa, y por eso varias funciones creadas en un bucle comparten una sola.", "s": "", "l": "python/02-funciones-y-scope"}, "funcion de orden superior": {"t": "función de orden superior", "d": "Una función que recibe otra función como argumento o devuelve una. Es posible porque una función es un objeto corriente.", "s": "", "l": "python/02-funciones-y-scope"}, "protocolo de iteracion": {"t": "protocolo de iteración", "d": "El contrato que hace recorrible a un objeto: iter() entrega un iterador y next() entrega un elemento cada vez, hasta lanzar StopIteration. El bucle for no hace otra cosa.", "s": "", "l": "python/03-comprehensions"}, "iterable": {"t": "iterable", "d": "Un objeto del que iter() obtiene un iterador. Una lista lo es y entrega uno nuevo en cada recorrido, así que se puede recorrer muchas veces.", "s": "", "l": "python/03-comprehensions"}, "iterador": {"t": "iterador", "d": "Un objeto que responde a next() y cuyo iter() se devuelve a sí mismo. Guarda la posición, de modo que se agota: el segundo recorrido no entrega nada.", "s": "", "l": "python/03-comprehensions"}, "comprehension": {"t": "comprehension", "d": "La forma de construir una colección describiendo sus elementos, como [f(x) for x in xs if c(x)]. Tiene ámbito propio, así que su variable de control no se filtra.", "s": "", "l": "python/03-comprehensions"}, "expresion generadora": {"t": "expresión generadora", "d": "La comprehension escrita entre paréntesis. No construye ninguna colección: devuelve un generador que produce los elementos de uno en uno según se piden.", "s": "", "l": "python/03-comprehensions"}, "generador": {"t": "generador", "d": "El objeto que devuelve una función con yield, o una expresión generadora. Es un iterador cuyo cuerpo queda suspendido entre dos elementos, con sus nombres locales vivos.", "s": "", "l": "python/03-comprehensions"}, "evaluacion perezosa": {"t": "evaluación perezosa", "d": "Calcular cada elemento solo cuando alguien lo pide. Es lo que permite recorrer un iterable enorme, o infinito, con memoria acotada.", "s": "", "l": "python/03-comprehensions"}, "cortocircuito": {"t": "cortocircuito", "d": "Detener un recorrido en cuanto la respuesta ya está decidida. any() se detiene en el primer verdadero y all() en el primer falso, y solo ahorran trabajo si el argumento es perezoso.", "s": "", "l": "python/03-comprehensions"}, "gestor de contexto": {"t": "gestor de contexto", "d": "Un objeto con __enter__ y __exit__, que la sentencia with usa para garantizar que la salida se ejecute pase lo que pase en el cuerpo: terminación normal, return, break o excepción.", "s": "", "l": "python/04-archivos-y-errores"}, "excepcion": {"t": "excepción", "d": "El objeto que señala un error y que interrumpe el flujo hasta que una cláusula except compatible lo captura. Las clases forman una jerarquía, y except E captura E y todas sus subclases.", "s": "", "l": "python/04-archivos-y-errores"}, "entorno virtual": {"t": "entorno virtual", "d": "Un directorio con su propio árbol de paquetes, cuya ruta se antepone en sys.path. No prohíbe nada: aísla porque la importación se detiene en el primer acierto.", "s": "", "l": "python/05-entorno-uv-git"}, "archivo de fijado": {"t": "archivo de fijado", "d": "El archivo que registra la versión exacta de cada dependencia, directa o indirecta. Se versiona, porque es lo que hace que el entorno se pueda reconstruir igual en otra máquina y en otro momento.", "s": "", "l": "python/05-entorno-uv-git"}, "resolucion de dependencias": {"t": "resolución de dependencias", "d": "Encontrar una asignación de versiones que satisfaga todas las restricciones a la vez. Puede no existir, aunque cada restricción por separado sea satisfacible.", "s": "", "l": "python/05-entorno-uv-git"}, "commit": {"t": "commit", "d": "Un objeto de git identificado por el hash de su contenido, que incluye el árbol de archivos y los identificadores de sus padres. Alterar uno cambia el identificador de todos sus descendientes.", "s": "", "l": "python/05-entorno-uv-git"}, "array": {"t": "array", "d": "La estructura de NumPy: un búfer contiguo, un dtype de ancho fijo, una forma y unos pasos. La forma y los pasos bastan para localizar cualquier elemento con una suma de productos.", "s": "", "l": "python/06-numpy-primer-contacto"}, "dtype": {"t": "dtype", "d": "El tipo común a todos los elementos de un array, de ancho fijo y conocido. Es lo que permite calcular la posición de un elemento en vez de seguir un puntero, y también lo que hace modular la aritmética entera.", "s": "", "l": "python/06-numpy-primer-contacto"}, "paso": {"t": "paso", "d": "Cuántos bytes hay que avanzar en el búfer al incrementar en uno el índice de una dimensión. Transponer permuta los pasos sin mover datos, y una dimensión difundida lleva paso cero.", "s": "", "l": "python/06-numpy-primer-contacto"}, "vista": {"t": "vista", "d": "Un array que comparte el búfer de otro con otra forma y otros pasos. Escribir en él modifica al original: es el aliasing de la Proposición 1.5 sobre el búfer.", "s": "", "l": "python/06-numpy-primer-contacto"}, "indexacion avanzada": {"t": "indexación avanzada", "d": "Indexar con una lista de índices o con una máscara booleana. Devuelve siempre una copia, porque una selección arbitraria no se puede describir con un paso constante.", "s": "", "l": "python/06-numpy-primer-contacto"}, "difusion": {"t": "difusión", "d": "La regla que permite operar arrays de formas distintas alineándolas por la derecha cuando cada par de dimensiones es igual o alguna vale 1. No duplica memoria: la dimensión difundida lleva paso cero.", "s": "", "l": "python/06-numpy-primer-contacto"}, "error irreducible": {"t": "error irreducible", "d": "La varianza σ² del ruido: la parte del error que ningún método puede bajar, porque no depende de X. Un modelo que acertara f exactamente seguiría equivocándose en esa cantidad.", "s": "", "l": "ml/01-aprendizaje-estadistico"}, "flexibilidad": {"t": "flexibilidad", "d": "Cuánto puede adaptarse un modelo a la forma de los datos. Al aumentarla cae el sesgo y sube la varianza, y por eso el error de prueba tiene forma de U.", "s": "", "l": "ml/01-aprendizaje-estadistico"}, "sobreajuste": {"t": "sobreajuste", "d": "Que el error de entrenamiento siga bajando mientras el de prueba sube. Ocurre cuando el aumento de varianza supera a la reducción de sesgo.", "s": "", "l": "ml/01-aprendizaje-estadistico"}, "variable indicadora": {"t": "variable indicadora", "d": "La columna que vale 1 en las observaciones de un nivel de un predictor cualitativo y 0 en las demás. Con k niveles se usan k−1: las k juntas suman la columna del intercepto y dejan la matriz sin rango completo.", "s": "", "l": "ml/02-diagnostico-regresion"}, "factor de inflacion de la varianza": {"t": "factor de inflación de la varianza", "d": "VIF = 1/(1−R²_j), con R²_j el de regresar el predictor j contra todos los demás. Es cuántas veces mayor es la varianza del coeficiente que si ese predictor fuera ortogonal al resto.", "s": "", "l": "ml/02-diagnostico-regresion"}, "heterocedasticidad": {"t": "heterocedasticidad", "d": "Que la varianza del ruido dependa de x. Deja el estimador insesgado y rompe el error estándar, de modo que el intervalo anunciado como del 95 % cubre menos.", "s": "", "l": "ml/02-diagnostico-regresion"}, "palanca": {"t": "palanca", "d": "El elemento h_ii de la diagonal de la matriz sombrero: cuánto influye una observación sobre su propio valor ajustado. Suman p entre todas, así que la media es p/n, y un punto de palanca alta tiene residuo pequeño por construcción.", "s": "", "l": "ml/02-diagnostico-regresion"}, "clasificacion": {"t": "clasificación", "d": "El problema de predecir a cuál de un conjunto finito de clases pertenece una observación, en lugar de predecir un número.", "s": "", "l": "ml/03-regresion-logistica"}, "regresion logistica": {"t": "regresión logística", "d": "El modelo que describe la probabilidad de una clase como la función logística de una combinación lineal de los predictores. Se ajusta por máxima verosimilitud.", "s": "", "l": "ml/03-regresion-logistica"}, "funcion logistica": {"t": "función logística", "d": "La función que lleva cualquier número real al intervalo abierto (0,1): sigma(z) = 1/(1+e^-z). Es la inversa del logit.", "s": "σ", "l": "ml/03-regresion-logistica"}, "logit": {"t": "logit", "d": "El logaritmo de las odds, log(p/(1-p)). Lleva una probabilidad de (0,1) a toda la recta real, y es la inversa de la función logística.", "s": "", "l": "ml/03-regresion-logistica"}, "odds": {"t": "odds", "d": "El cociente p/(1-p) entre la probabilidad de que algo ocurra y la de que no. Vale 1 cuando la probabilidad es un medio.", "s": "", "l": "ml/03-regresion-logistica"}, "separacion perfecta": {"t": "separación perfecta", "d": "La situación en que alguna combinación de los predictores separa las dos clases sin ningún error. Bajo ella la máxima verosimilitud no alcanza su máximo y los coeficientes no están definidos.", "s": "", "l": "ml/03-regresion-logistica"}, "reduccion": {"t": "reducción", "d": "Plegar con una operación asociativa todas las posiciones de un eje, que desaparece del resultado. Encadenar dos reducciones corre la numeración de los ejes: el eje j del original pasa a ser el j−1.", "s": "", "l": "python/07-ejes-y-reducciones"}, "elemento neutro": {"t": "elemento neutro", "d": "Un valor e que cumple e ⊕ v = v para todo v. Es lo único que una reducción puede devolver sobre un eje de tamaño cero, y por eso la suma responde sobre un eje vacío y el máximo lanza ValueError.", "s": "", "l": "python/07-ejes-y-reducciones"}, "modelo generativo": {"t": "modelo generativo", "d": "Un modelo que especifica las probabilidades a priori de cada clase y la densidad de X dentro de cada una, y obtiene la probabilidad de la clase dado X invirtiéndolo con el teorema de Bayes.", "s": "", "l": "ml/04-modelos-generativos"}, "analisis discriminante lineal": {"t": "análisis discriminante lineal", "d": "El modelo generativo con densidades normales y una covarianza común a todas las clases. El término cuadrático es el mismo en cada clase y se cancela, así que la frontera de decisión es un hiperplano.", "s": "", "l": "ml/04-modelos-generativos"}, "naive bayes": {"t": "naive Bayes", "d": "El modelo generativo que supone los predictores independientes dentro de cada clase, lo que equivale a covarianzas diagonales. Estima 2Kp parámetros y su frontera sigue siendo cuadrática.", "s": "", "l": "ml/04-modelos-generativos"}, "modelo lineal generalizado": {"t": "modelo lineal generalizado", "d": "Un modelo con tres piezas: una distribución de la familia exponencial para la respuesta, un predictor lineal xᵀβ y una función de enlace que los conecta. La regresión lineal, la logística y la de Poisson son casos suyos.", "s": "", "l": "ml/05-modelos-lineales-generalizados"}, "funcion de enlace": {"t": "función de enlace", "d": "La función creciente g que conecta la media de la respuesta con el predictor lineal, g(μ) = xᵀβ. El enlace log garantiza medias positivas y el logit las mantiene entre 0 y 1.", "s": "", "l": "ml/05-modelos-lineales-generalizados"}, "regresion de poisson": {"t": "regresión de Poisson", "d": "El modelo lineal generalizado para conteos: la respuesta es Poisson y log μ = xᵀβ. Su log-verosimilitud es cóncava y sus coeficientes se leen como factores multiplicativos sobre la media.", "s": "", "l": "ml/05-modelos-lineales-generalizados"}, "score": {"t": "score", "d": "El gradiente de la log-verosimilitud. Anularlo da Xᵀ(y − μ̂) = 0: el residuo es ortogonal a las columnas del diseño, y con intercepto los valores ajustados suman lo observado.", "s": "", "l": "ml/05-modelos-lineales-generalizados"}, "orden de almacenamiento": {"t": "orden de almacenamiento", "d": "Cómo se reparten los pasos entre los ejes. En orden C el último índice avanza de uno en uno por el búfer; en orden F lo hace el primero. Transponer intercambia el uno por el otro.", "s": "", "l": "python/08-reshape-orden-y-ventanas"}, "ventanas deslizantes": {"t": "ventanas deslizantes", "d": "La matriz cuyas filas son los tramos consecutivos de un array. Es una vista de forma (n−w+1, w) y pasos (s, s), así que tiene más elementos que el original y no copia ni un byte.", "s": "", "l": "python/08-reshape-orden-y-ventanas"}, "validacion cruzada": {"t": "validación cruzada", "d": "Repartir las observaciones en bloques, ajustar con todos menos uno y medir sobre el apartado, y promediar. Estima el error de un modelo entrenado con n(k−1)/k observaciones, y solo es honesta si el bloque apartado no interviene en ninguna decisión del ajuste.", "s": "", "l": "ml/06-validacion-cruzada"}, "pliegue": {"t": "pliegue", "d": "Cada uno de los bloques en que la validación cruzada reparte las observaciones. Con k pliegues, cada uno se aparta por turno para medir mientras los demás entrenan.", "s": "", "l": "ml/06-validacion-cruzada"}, "apalancamiento": {"t": "apalancamiento", "d": "La entrada diagonal h_ii de la matriz sombrero: la parte del ajuste en la observación i que se debe a su propia respuesta. Los n apalancamientos suman p+1, y 1−h_ii es lo que corrige el residuo al dejar esa observación fuera.", "s": "", "l": "ml/06-validacion-cruzada"}, "series": {"t": "Series", "d": "La estructura de una dimensión de pandas: un array de valores con su dtype, más un índice que asigna una etiqueta a cada posición. El índice es lo único que tiene y un array no.", "s": "", "l": "python/09-pandas-series-dataframe"}, "indice de pandas": {"t": "índice de pandas", "d": "La aplicación de etiquetas a posiciones que lleva toda Series y todo DataFrame. Las operaciones lo consultan antes de combinar valores, y por eso la aritmética alinea por etiqueta y no por posición.", "s": "", "l": "python/09-pandas-series-dataframe"}, "seleccion del mejor subconjunto": {"t": "selección del mejor subconjunto", "d": "Ajustar los 2^p modelos que se pueden formar con p predictores, quedarse con el de menor RSS en cada tamaño y elegir entre esos p+1 finalistas por un criterio que estime el error de prueba. El primer paso es exacto y el segundo es el que decide.", "s": "", "l": "ml/07-seleccion-de-subconjuntos"}, "seleccion paso a paso": {"t": "selección paso a paso", "d": "Recorrer los tamaños añadiendo (hacia adelante) o quitando (hacia atrás) una variable por vez, siempre la que más baja el RSS. Mira 1+p(p+1)/2 modelos en vez de 2^p, y a cambio puede no encontrar el mejor subconjunto de un tamaño dado.", "s": "", "l": "ml/07-seleccion-de-subconjuntos"}, "optimismo": {"t": "optimismo", "d": "Lo que el error de entrenamiento subestima al de prueba. En mínimos cuadrados vale exactamente 2σ²(d+1)/n: cada coeficiente estimado cuesta 2σ²/n.", "s": "", "l": "ml/07-seleccion-de-subconjuntos"}, "error de entrenamiento": {"t": "error de entrenamiento", "d": "El error medio medido sobre las mismas observaciones que se usaron para ajustar. Siempre se puede calcular, y siempre premia al modelo más grande.", "s": "", "l": "ml/07-seleccion-de-subconjuntos"}, "error de prueba": {"t": "error de prueba", "d": "El error medio sobre observaciones que no intervinieron en el ajuste. Es la cantidad que se quiere minimizar y casi nunca se puede calcular.", "s": "", "l": "ml/07-seleccion-de-subconjuntos"}, "cp de mallows": {"t": "cp de mallows", "d": "El error de entrenamiento corregido por su propio optimismo: (RSS + 2(d+1)σ̂²)/n. Con σ² conocida es un estimador insesgado del error de prueba.", "s": "", "l": "ml/07-seleccion-de-subconjuntos"}, "criterio de informacion de akaike": {"t": "criterio de información de akaike", "d": "Criterio de selección que penaliza cada parámetro con un factor 2. En mínimos cuadrados con errores normales ordena los modelos igual que el Cp de Mallows.", "s": "", "l": "ml/07-seleccion-de-subconjuntos"}, "criterio de informacion bayesiano": {"t": "criterio de información bayesiano", "d": "Criterio de selección que penaliza cada parámetro con log n en vez de 2. Como log n > 2 en cuanto n ≥ 8, nunca elige un modelo más grande que el Cp.", "s": "", "l": "ml/07-seleccion-de-subconjuntos"}, "coeficiente de determinacion ajustado": {"t": "coeficiente de determinación ajustado", "d": "El R² corregido por grados de libertad: 1 − (RSS/(n−d−1))/(TSS/(n−1)). Sube al añadir una variable si y solo si el estadístico t de esa variable supera 1 en valor absoluto, umbral que el ruido puro pasa cerca de un tercio de las veces.", "s": "", "l": "ml/07-seleccion-de-subconjuntos"}, "modelo anidado": {"t": "modelo anidado", "d": "Un modelo cuyos predictores son un subconjunto de los de otro. Entre modelos anidados el RSS nunca puede subir al pasar del pequeño al grande.", "s": "", "l": "ml/07-seleccion-de-subconjuntos"}, "suma de cuadrados residual": {"t": "suma de cuadrados residual", "d": "La suma de los cuadrados de los residuos, RSS. Es lo que minimizan los mínimos cuadrados, y no crece nunca al añadir predictores.", "s": "", "l": "ml/07-seleccion-de-subconjuntos"}, "estadistico t": {"t": "estadístico t", "d": "El cociente entre un coeficiente estimado y su error estándar. Mide en cuántos errores estándar el coeficiente se aparta de cero.", "s": "", "l": "ml/07-seleccion-de-subconjuntos"}, "formato delimitado": {"t": "formato delimitado", "d": "Un archivo de texto donde cada línea es una fila y un separador marca las columnas. No guarda tipos: todo lo que se escribe en él es texto, y el tipo se vuelve a adivinar al leer.", "s": "", "l": "python/10-carga-formatos-y-limpieza"}, "inferencia de tipo": {"t": "inferencia de tipo", "d": "Lo que hace el lector de un archivo de texto para decidir el dtype de cada columna a partir de los valores que ve. Depende de qué valores ve, así que leer el mismo archivo por bloques puede dar tipos distintos para la misma columna.", "s": "", "l": "python/10-carga-formatos-y-limpieza"}, "valor faltante": {"t": "valor faltante", "d": "La marca de que un dato no está. En pandas la lleva NaN para números, NaT para fechas y None para objetos, y todas comparten que no son iguales a sí mismas.", "s": "", "l": "python/10-carga-formatos-y-limpieza"}, "bloque de lectura": {"t": "bloque de lectura", "d": "Cada trozo de filas que devuelve un lector con chunksize. Permite leer un archivo que no cabe en memoria, a costa de que la inferencia de tipo se haga por bloque y no sobre la columna entera.", "s": "", "l": "python/10-carga-formatos-y-limpieza"}, "union interna": {"t": "unión interna", "d": "La combinación de dos tablas que devuelve una fila por cada par de filas con la misma clave. Su número de filas es la suma, sobre las claves, del producto de las multiplicidades en cada lado.", "s": "", "l": "python/10-carga-formatos-y-limpieza"}, "multiplicidad": {"t": "multiplicidad", "d": "El número de veces que una clave aparece en una tabla. Es lo que decide cuántas filas produce esa clave en una unión.", "s": "", "l": "python/10-carga-formatos-y-limpieza"}, "normalizacion de cadenas": {"t": "normalización de cadenas", "d": "Llevar las cadenas a una forma común, por ejemplo quitando espacios y pasando a minúsculas, para que variantes de la misma clave coincidan. No es inyectiva: puede unir claves que eran distintas a propósito.", "s": "", "l": "python/10-carga-formatos-y-limpieza"}, "tipo de extension": {"t": "tipo de extensión", "d": "Un dtype de pandas que no viene de NumPy y que sí admite faltantes sin cambiar de tipo, como Int64 o string. Es el remedio cuando un solo faltante convertiría una columna entera en float64.", "s": "", "l": "python/10-carga-formatos-y-limpieza"}, "regresion ridge": {"t": "regresión ridge", "d": "Minimizar el RSS más λ veces la suma de los cuadrados de los coeficientes. Tiene forma cerrada (XᵀX+λI)⁻¹Xᵀy, que existe y es única para todo λ>0 aunque XᵀX sea singular, y encoge sin anular.", "s": "", "l": "ml/08-ridge-y-lasso"}, "lasso": {"t": "lasso", "d": "Minimizar el RSS más λ veces la suma de los valores absolutos de los coeficientes. En diseño ortonormal su solución es el umbral suave, que manda a cero exacto todo coeficiente cuyo valor absoluto no supere λ/2.", "s": "", "l": "ml/08-ridge-y-lasso"}, "encogimiento": {"t": "encogimiento", "d": "Acercar los coeficientes estimados hacia cero a propósito, aceptando sesgo para bajar la varianza. Siempre existe un grado de encogimiento que mejora el error cuadrático medio de mínimos cuadrados.", "s": "", "l": "ml/08-ridge-y-lasso"}, "umbral suave": {"t": "umbral suave", "d": "La operación sign(b)·máx(|b|−c, 0): resta c al valor absoluto y corta en cero. Es la solución del lasso en diseño ortonormal, y es lo que le da los ceros exactos.", "s": "", "l": "ml/08-ridge-y-lasso"}, "grados de libertad efectivos": {"t": "grados de libertad efectivos", "d": "La traza de la matriz que lleva y a su ajuste. En ridge valen la suma de d_j²/(d_j²+λ) sobre los valores singulares, bajan de forma continua del rango de X a cero, y ocupan el lugar del p+1 de mínimos cuadrados.", "s": "", "l": "ml/08-ridge-y-lasso"}, "parametro de regularizacion": {"t": "parámetro de regularización", "d": "El número λ que pone precio a la complejidad en ridge y en lasso. No se estima de los datos con el mismo ajuste: se elige por validación cruzada o por un criterio que corrija el optimismo.", "s": "", "l": "ml/08-ridge-y-lasso"}, "estandarizacion": {"t": "estandarización", "d": "Llevar cada predictor a media cero y desviación típica uno. Ridge y lasso lo exigen, porque penalizan la suma de los coeficientes y esa suma cambia si se cambia la unidad de una columna.", "s": "", "l": "ml/08-ridge-y-lasso"}, "indice jerarquico": {"t": "índice jerárquico", "d": "Un índice cuyas etiquetas son tuplas de dos o más niveles. Representa una tabla de dos entradas guardando solo las combinaciones observadas, no el producto entero de los niveles.", "s": "", "l": "python/11-wrangling-joins-y-reshape"}, "union externa": {"t": "unión externa", "d": "La combinación que conserva todas las claves de los dos lados, rellenando con faltantes lo que no aparece en uno de ellos. Sus filas son la suma sobre las claves de máx(m₁,1)·máx(m₂,1).", "s": "", "l": "python/11-wrangling-joins-y-reshape"}, "union por la izquierda": {"t": "unión por la izquierda", "d": "La combinación que conserva todas las filas de la tabla izquierda. Solo conserva su número de filas si la clave es única en la tabla derecha.", "s": "", "l": "python/11-wrangling-joins-y-reshape"}, "forma larga": {"t": "forma larga", "d": "La disposición con una fila por observación y una columna que dice a qué variable corresponde. Guarda solo lo observado.", "s": "", "l": "python/11-wrangling-joins-y-reshape"}, "forma ancha": {"t": "forma ancha", "d": "La disposición con una fila por unidad y una columna por variable. Reserva el producto entero de los niveles, así que crea un faltante por cada combinación no observada.", "s": "", "l": "python/11-wrangling-joins-y-reshape"}, "desapilar": {"t": "desapilar", "d": "Llevar un nivel del índice jerárquico a las columnas, pasando de la forma larga a la ancha. Es la operación que materializa el producto de los niveles.", "s": "", "l": "python/11-wrangling-joins-y-reshape"}, "densidad de una tabla": {"t": "densidad de una tabla", "d": "La proporción de combinaciones observadas frente a las posibles, n/(i·j). Es lo que decide cuánto cuesta la forma ancha frente a la larga.", "s": "", "l": "python/11-wrangling-joins-y-reshape"}, "alta dimension": {"t": "alta dimensión", "d": "La situación en que el número de predictores se acerca o supera al de observaciones. Ahí mínimos cuadrados ajusta sin error aunque no haya ninguna relación, y el R² de entrenamiento deja de medir nada.", "s": "", "l": "ml/09-alta-dimension"}, "interpolacion exacta": {"t": "interpolación exacta", "d": "Que el modelo pase por todos los puntos, con RSS cero. Ocurre siempre que el diseño tenga al menos tantas columnas como observaciones, con independencia de que los predictores sirvan o no.", "s": "", "l": "ml/09-alta-dimension"}, "solucion de norma minima": {"t": "solución de norma mínima", "d": "De entre todas las que ajustan igual de bien, la de menor norma. Es la que devuelven lstsq y la pseudoinversa cuando el sistema está indeterminado.", "s": "", "l": "ml/09-alta-dimension"}, "correlacion espuria": {"t": "correlación espuria", "d": "La que aparece entre la respuesta y predictores que no tienen ninguna relación con ella, solo por haber mirado muchos. Crece con el número de predictores examinados.", "s": "", "l": "ml/09-alta-dimension"}, "partir-aplicar-combinar": {"t": "partir-aplicar-combinar", "d": "El patrón de `groupby`: partir las filas por el valor de una clave, aplicar una función a cada bloque y recomponer el resultado. Lo que cambia entre `agg` y `transform` es la forma de la recomposición.", "s": "", "l": "python/12-groupby-y-agregacion"}, "agregacion": {"t": "agregación", "d": "La operación que devuelve un valor por grupo, de modo que el resultado tiene tantas filas como grupos y pierde el índice original.", "s": "", "l": "python/12-groupby-y-agregacion"}, "transformacion por grupo": {"t": "transformación por grupo", "d": "La operación que devuelve un valor por fila, calculado con su grupo, de modo que el resultado se alinea con la tabla de partida y conserva su índice.", "s": "", "l": "python/12-groupby-y-agregacion"}, "media ponderada": {"t": "media ponderada", "d": "El promedio que pesa cada grupo por su tamaño. Coincide con la media global; la media sin ponderar de las medias de grupo no, salvo que el tamaño y la media del grupo no covaríen.", "s": "", "l": "python/12-groupby-y-agregacion"}, "categoria declarada": {"t": "categoría declarada", "d": "Un valor admitido por un dtype categórico aunque no aparezca en los datos. Al agrupar con observed=False produce un grupo vacío, que sum() rellena con cero y mean() con faltante.", "s": "", "l": "python/12-groupby-y-agregacion"}, "funcion base": {"t": "función base", "d": "Cada una de las funciones fijas b_j cuya combinación lineal forma el modelo. Elegir una base convierte un ajuste no lineal en x en unos mínimos cuadrados ordinarios sobre las columnas b_j(x).", "s": "", "l": "ml/10-bases-y-splines"}, "base de potencias": {"t": "base de potencias", "d": "La base 1, x, x², …, x^d, cuya matriz de diseño es la de Vandermonde. Genera los polinomios de grado d y está mal condicionada: su número de condición crece de forma exponencial con el grado.", "s": "", "l": "ml/10-bases-y-splines"}, "funcion escalon": {"t": "función escalón", "d": "La indicadora de un tramo de la recta. Con una partición en tramos, la base de indicadoras es ortogonal y el ajuste por mínimos cuadrados devuelve la media de la respuesta en cada tramo.", "s": "", "l": "ml/10-bases-y-splines"}, "spline cubico": {"t": "spline cúbico", "d": "Una función que es un polinomio cúbico en cada tramo entre nudos y de clase C² en los nudos. Con K nudos tiene K+4 grados de libertad.", "s": "", "l": "ml/10-bases-y-splines"}, "nudo": {"t": "nudo", "d": "Cada punto donde un spline cambia de tramo. En la base de potencias truncadas, su coeficiente es el salto de la tercera derivada dividido entre seis.", "s": "", "l": "ml/10-bases-y-splines"}, "potencias truncadas": {"t": "potencias truncadas", "d": "La base 1, x, x², x³ y (x−ξ)³₊ por cada nudo ξ. Genera exactamente los splines cúbicos, y cada columna nueva añade un salto libre de la tercera derivada.", "s": "", "l": "ml/10-bases-y-splines"}, "figura": {"t": "figura", "d": "El objeto que contiene todo el gráfico. Cuelgan de ella uno o varios ejes, y de cada eje los artistas. El archivo de imagen es una proyección de ese árbol, no el gráfico.", "s": "", "l": "python/13-visualizacion"}, "eje": {"t": "eje", "d": "La región donde se dibuja, con sus dos escalas y sus marcas. Es el objeto al que se le piden las operaciones de dibujo cuando se quiere saber dónde van a ir.", "s": "", "l": "python/13-visualizacion"}, "artista": {"t": "artista", "d": "Cada elemento dibujable de un eje: una línea, una colección de puntos, un rectángulo. Guarda los datos que representa, así que se le pueden pedir de vuelta.", "s": "", "l": "python/13-visualizacion"}, "eje actual": {"t": "eje actual", "d": "El eje sobre el que dibuja la interfaz pyplot cuando no se le dice cuál. Es una variable global, y cuál sea depende de lo que haya ocurrido antes en el programa.", "s": "", "l": "python/13-visualizacion"}, "limites automaticos": {"t": "límites automáticos", "d": "El rango que el eje se pone solo: el de los datos más un margen del 5 % del recorrido a cada lado. No incluye el cero salvo que los datos lo rodeen.", "s": "", "l": "python/13-visualizacion"}, "ancho de bin": {"t": "ancho de bin", "d": "La anchura de cada barra de un histograma. Con bordes explícitos queda fijada; por omisión son diez bins repartidos sobre el recorrido de los datos, así que la decide un par de valores extremos.", "s": "", "l": "python/13-visualizacion"}, "suavizador lineal": {"t": "suavizador lineal", "d": "Un método cuyo ajuste se escribe ŷ = S y con S dependiente solo de los predictores y del parámetro de suavizado, nunca de la respuesta. Casi todo este capítulo lo es, y por eso sus grados de libertad se leen igual: como la traza de S.", "s": "", "l": "ml/11-suavizado-y-gams"}, "matriz de suavizado": {"t": "matriz de suavizado", "d": "La matriz S que lleva la respuesta a su ajuste. Su traza son los grados de libertad efectivos, y sus filas dicen qué peso tiene cada observación en el ajuste de cada punto.", "s": "", "l": "ml/11-suavizado-y-gams"}, "spline de suavizado": {"t": "spline de suavizado", "d": "El que minimiza el RSS más λ veces la integral del cuadrado de la segunda derivada. No hay que elegir nudos: la penalización decide cuánta curvatura se permite.", "s": "", "l": "ml/11-suavizado-y-gams"}, "regresion local": {"t": "regresión local", "d": "Ajustar en cada punto una recta o un polinomio con las observaciones cercanas, pesadas por su distancia. Es un suavizador lineal cuya matriz no es simétrica.", "s": "", "l": "ml/11-suavizado-y-gams"}, "ancho de banda": {"t": "ancho de banda", "d": "La anchura de la ventana de la regresión local. Hace el papel de λ: al ensancharla bajan los grados de libertad y el ajuste se aplana.", "s": "", "l": "ml/11-suavizado-y-gams"}, "modelo aditivo": {"t": "modelo aditivo", "d": "Un modelo de la forma α + Σ f_j(x_j), con una función por predictor. Conserva la interpretación por variable de la regresión lineal y deja que cada efecto sea curvo.", "s": "", "l": "ml/11-suavizado-y-gams"}, "backfitting": {"t": "backfitting", "d": "El algoritmo que ajusta un modelo aditivo suavizando por turnos el residuo parcial de cada variable. Con suavizadores lineales converge, y en el caso de rectas llega a la solución de mínimos cuadrados.", "s": "", "l": "ml/11-suavizado-y-gams"}, "residuo parcial": {"t": "residuo parcial", "d": "Lo que queda de la respuesta al restarle el intercepto y todas las funciones menos una. Es lo que backfitting le da a suavizar al turno de esa variable.", "s": "", "l": "ml/11-suavizado-y-gams"}, "remuestreo": {"t": "remuestreo", "d": "Cambiar la frecuencia de una serie. Bajar de frecuencia es agrupar por intervalo y agregar, con la misma partición de la lección 12; subir de frecuencia no produce datos nuevos, solo huecos que hay que decidir cómo rellenar.", "s": "", "l": "python/14-series-de-tiempo"}, "frecuencia": {"t": "frecuencia", "d": "El paso regular de un índice temporal, escrito con un alias como D para días o MS para inicios de mes. Determina los bordes de los intervalos al remuestrear.", "s": "", "l": "python/14-series-de-tiempo"}, "ventana movil": {"t": "ventana móvil", "d": "El conjunto de las k observaciones que terminan en cada punto, o que lo rodean si está centrada. Promediarla es un suavizador lineal, y la versión que termina en el punto va retrasada.", "s": "", "l": "python/14-series-de-tiempo"}, "desplazamiento": {"t": "desplazamiento", "d": "Mover los valores de una serie respecto de su índice, que queda intacto. Es lo que permite comparar cada observación con la anterior, y deja un faltante en el extremo.", "s": "", "l": "python/14-series-de-tiempo"}, "hora ambigua": {"t": "hora ambigua", "d": "Una hora local que ocurre dos veces por el cambio de hora. No se puede convertir a instante sin decir cuál de las dos, y por eso la librería se niega en lugar de adivinar.", "s": "", "l": "python/14-series-de-tiempo"}, "hora inexistente": {"t": "hora inexistente", "d": "Una hora local que no llega a ocurrir porque el reloj salta sobre ella. Como la ambigua, exige una decisión explícita.", "s": "", "l": "python/14-series-de-tiempo"}, "vectorizar": {"t": "vectorizar", "d": "Sustituir un bucle escrito en Python por una operación que recorre el arreglo entero dentro de código compilado. No cambia las operaciones aritméticas que se hacen: cambia quién las ordena.", "s": "", "l": "python/15-rendimiento"}, "arreglo temporal": {"t": "arreglo temporal", "d": "El arreglo que una operación intermedia crea para guardar su resultado. Una expresión con varias operaciones crea uno por cada una, y con datos grandes eso es lo que decide si el cálculo cabe en memoria.", "s": "", "l": "python/15-rendimiento"}, "preasignar": {"t": "preasignar", "d": "Crear el arreglo del tamaño final antes de llenarlo, en lugar de hacerlo crecer. Evita que cada añadido copie lo que ya había.", "s": "", "l": "python/15-rendimiento"}, "amortizado": {"t": "amortizado", "d": "El coste medio por operación cuando unas pocas son caras y el resto baratas. Una lista de Python reserva de más al crecer, así que su añadido es amortizado constante aunque algunos realojen.", "s": "", "l": "python/15-rendimiento"}, "constante oculta": {"t": "constante oculta", "d": "El factor que multiplica a la complejidad y que la notación asintótica esconde. Vectorizar no cambia la complejidad de un cálculo; cambia esta constante, y por eso importa tanto en la práctica.", "s": "", "l": "python/15-rendimiento"}, "reproducible": {"t": "reproducible", "d": "Que volver a ejecutar el mismo cauce sobre los mismos datos devuelva bit a bit lo mismo. Exige fijar la semilla y también el orden de las filas, porque la suma en coma flotante no es asociativa.", "s": "", "l": "python/16-anatomia-de-un-proyecto"}, "huella": {"t": "huella", "d": "El resumen criptográfico del contenido de un artefacto. Dos artefactos con la misma huella son el mismo, y cambiar un solo valor la cambia entera.", "s": "", "l": "python/16-anatomia-de-un-proyecto"}, "manifiesto": {"t": "manifiesto", "d": "El registro que acompaña a una salida y guarda la huella de sus entradas. Es lo que permite decir de dónde salió un número sin volver a ejecutarlo todo.", "s": "", "l": "python/16-anatomia-de-un-proyecto"}, "cauce": {"t": "cauce", "d": "La sucesión de pasos que lleva de los datos crudos al resultado publicado. Cada paso declara qué lee y qué escribe, y de ahí sale su grafo de dependencias.", "s": "", "l": "python/16-anatomia-de-un-proyecto"}, "grafo aciclico dirigido": {"t": "grafo acíclico dirigido", "d": "Un grafo con flechas y sin ciclos. Un cauce lo es si ningún paso lee lo que un paso posterior escribe, y solo entonces existe un orden de ejecución válido.", "s": "", "l": "python/16-anatomia-de-un-proyecto"}, "orden topologico": {"t": "orden topológico", "d": "Una ordenación de los pasos en la que cada uno va después de aquellos de los que depende. Existe si y solo si el grafo es acíclico.", "s": "", "l": "python/16-anatomia-de-un-proyecto"}, "arbol de regresion": {"t": "árbol de regresión", "d": "Una partición del espacio de predictores en regiones, obtenida por cortes sucesivos de la forma x_j ≤ t, con una constante por región: la media de la respuesta ahí.", "s": "", "l": "ml/12-arboles-de-decision"}, "particion recursiva binaria": {"t": "partición recursiva binaria", "d": "El procedimiento que construye un árbol: en cada nodo se prueba cada corte posible de cada variable, se toma el de mayor caída del RSS y se repite dentro de los dos lados.", "s": "", "l": "ml/12-arboles-de-decision"}, "hoja": {"t": "hoja", "d": "Una región de la partición de un árbol: un nodo que ya no se corta. El número de hojas es el tamaño |T| del árbol y hace de número de parámetros en el criterio de poda.", "s": "|T|", "l": "ml/12-arboles-de-decision"}, "algoritmo voraz": {"t": "algoritmo voraz", "d": "El que en cada paso toma la mejor opción inmediata sin mirar qué opciones quedarán después. El árbol se construye así, y por eso puede no ver estructura que solo aparece dos niveles más abajo.", "s": "", "l": "ml/12-arboles-de-decision"}, "poda por coste-complejidad": {"t": "poda por coste-complejidad", "d": "Crecer el árbol de más y quedarse con el subárbol que minimiza RSS + α·(número de hojas). Al subir α el tamaño no crece nunca, y α se elige por validación cruzada.", "s": "α", "l": "ml/12-arboles-de-decision"}, "impureza": {"t": "impureza", "d": "Una medida del desorden de un nodo, nula cuando todas sus observaciones son de la misma clase. Las tres usuales son el error de clasificación, el índice de Gini y la entropía.", "s": "φ", "l": "ml/12-arboles-de-decision"}, "indice de gini": {"t": "índice de Gini", "d": "La impureza 2p(1−p) con dos clases, o Σ p_k(1−p_k) en general. Es estrictamente cóncava, así que distingue entre cortes que el error de clasificación empata.", "s": "G", "l": "ml/12-arboles-de-decision"}, "entropia": {"t": "entropía", "d": "La impureza −Σ p_k log₂ p_k. Como el índice de Gini, es estrictamente cóncava, y por eso sirve para crecer un árbol donde el error de clasificación no discrimina.", "s": "D", "l": "ml/12-arboles-de-decision"}, "bagging": {"t": "bagging", "d": "Promediar B árboles sin podar, cada uno ajustado sobre un remuestreo con reemplazo. Ataca la varianza del árbol suelto, no su sesgo, y por eso los árboles no se podan.", "s": "", "l": "ml/13-bagging-bosques-y-boosting"}, "error fuera de la bolsa": {"t": "error fuera de la bolsa", "d": "El error estimado con las observaciones que cada remuestreo dejó fuera, unas (1−1/n)ⁿ ≈ 37 % por árbol. Sale gratis, sin apartar datos, pero evalúa un conjunto de unos B/e árboles y no de B.", "s": "", "l": "ml/13-bagging-bosques-y-boosting"}, "bosque aleatorio": {"t": "bosque aleatorio", "d": "Bagging en el que cada nodo sortea m de los p predictores y busca el corte solo entre ellos. Con m = p es bagging. Baja siempre la correlación entre árboles, y mejora el error solo cuando hay predictores que se sustituyen unos a otros.", "s": "m", "l": "ml/13-bagging-bosques-y-boosting"}, "impulso": {"t": "impulso", "d": "Ajustar árboles pequeños uno tras otro, cada uno al residuo que dejan los anteriores, sumando λ veces su ajuste. Es descenso por gradiente en el espacio de funciones, y a diferencia del bagging puede sobreajustar al subir el número de pasos.", "s": "λ", "l": "ml/13-bagging-bosques-y-boosting"}, "tasa de aprendizaje": {"t": "tasa de aprendizaje", "d": "El factor λ que multiplica cada corrección del impulso. Un paso baja el RSS en (2λ−λ²)‖g‖², así que el método solo converge con 0 < λ < 2; en la práctica se usa pequeña y se compensa con más pasos.", "s": "λ", "l": "ml/13-bagging-bosques-y-boosting"}};
window.GLOSARIO_SIMBOLOS = {"μ": {"t": "μ", "d": "La media de una distribución, es decir E[X]. Se usa cuando se la trata como una constante conocida. Su versión muestral es x̄.", "s": "mu", "l": "estadistica/04-esperanza-varianza-momentos"}, "σ": {"t": "σ", "d": "La desviación estándar: la raíz de la varianza, en las mismas unidades que la variable. σ² es la varianza.", "s": "sigma", "l": "estadistica/04-esperanza-varianza-momentos"}, "Σ": {"t": "Σ", "d": "Dos cosas según el tamaño y el contexto. Como operador, el símbolo de suma: Σᵢ₌₁ⁿ xᵢ es «suma x₁ + … + xₙ». Como matriz, la de covarianzas de un vector aleatorio, cuyos eigenvalores son las varianzas en las direcciones principales. **La tabla de notación de la lección manda.**", "s": "sigma mayúscula", "l": "estadistica/01-variables-aleatorias"}, "λ": {"t": "λ", "d": "La tasa de una distribución exponencial o de Poisson: cuántos eventos por unidad de tiempo. La media de la exponencial es 1/λ.", "s": "lambda", "l": "estadistica/03-distribuciones-analiticas"}, "α": {"t": "α", "d": "Símbolo sobrecargado: se usa con al menos ocho sentidos en el sitio. Los más frecuentes son el nivel de significancia de una prueba, el exponente de la cola de una Pareto, un escalar cualquiera y un parámetro de forma. **La tabla de notación de la lección que se esté leyendo es la que manda.**", "s": "alfa", "l": "estadistica/03-distribuciones-analiticas"}, "β": {"t": "β", "d": "Símbolo sobrecargado: se usa con más de diez sentidos en el sitio. El más frecuente son los coeficientes de un modelo de regresión, con β̂ para los estimados; también la probabilidad de error de tipo II —la potencia es 1 − β—, un parámetro de forma y un coeficiente de momento. **La tabla de notación de la lección que se esté leyendo es la que manda.**", "s": "beta", "l": "matematica/06-minimos-cuadrados"}, "γ": {"t": "γ", "d": "Con subíndice, un momento estandarizado: γ₁ es la asimetría y γ₂ la curtosis en exceso.", "s": "gamma", "l": "estadistica/04-esperanza-varianza-momentos"}, "ρ": {"t": "ρ", "d": "La correlación poblacional entre dos variables. Su versión muestral se escribe r.", "s": "rho", "l": "estadistica/05-covarianza-correlacion"}, "θ": {"t": "θ", "d": "Símbolo sobrecargado. En estadística, el parámetro verdadero y desconocido que se quiere estimar, con θ̂ para el estimador; en álgebra lineal, el ángulo entre dos vectores, cuyo coseno es la correlación. **La tabla de notación de la lección que se esté leyendo es la que manda.**", "s": "theta", "l": "matematica/04-producto-interno"}, "Φ": {"t": "Φ", "d": "La función de distribución acumulada de la normal estándar: Φ(z) es la probabilidad de que una normal de media 0 y desviación 1 sea menor o igual que z. Φ⁻¹ es su inversa, la función probit.", "s": "Phi", "l": "estadistica/03-distribuciones-analiticas"}, "κ": {"t": "κ", "d": "El número de condición de una matriz: cuánto amplifica los errores de redondeo. Cuanto mayor, más precisión se pierde al resolver el sistema.", "s": "kappa", "l": "matematica/06-minimos-cuadrados"}, "δ": {"t": "δ", "d": "Una cantidad pequeña, con el sentido preciso variando por lección: un desplazamiento en optimización, la tolerancia de una definición de límite, o el tamaño real de un efecto, μ − μ₀, en pruebas de hipótesis. Δ (mayúscula) suele marcar una diferencia entre dos valores. **La tabla de notación de la lección manda.**", "s": "delta", "l": "matematica/07-gram-schmidt-qr"}, "ε": {"t": "ε", "d": "Símbolo sobrecargado. En estadística, el término de error de un modelo; en cómputo numérico, la precisión de la máquina; en análisis, una cantidad arbitrariamente pequeña. **La tabla de notación de la lección manda.**", "s": "épsilon", "l": "matematica/06-minimos-cuadrados"}, "π": {"t": "π", "d": "La constante 3.14159…, que aparece en la densidad de la normal. Con subíndices también se usa para probabilidades.", "s": "pi", "l": "estadistica/03-distribuciones-analiticas"}, "x̄": {"t": "x̄", "d": "La media muestral: el promedio de los n datos observados. Es una estimación de μ, que no se conoce.", "s": "equis barra", "l": "estadistica/04-esperanza-varianza-momentos"}, "x̂": {"t": "x̂", "d": "El sombrero marca un valor estimado o ajustado, no observado. ŷ son las predicciones del modelo; β̂ los coeficientes estimados.", "s": "equis sombrero", "l": "matematica/06-minimos-cuadrados"}, "x̃": {"t": "x̃", "d": "La tilde marca una variable centrada: se le restó su media, así que su media es cero.", "s": "equis tilde", "l": "estadistica/05-covarianza-correlacion"}, "ᵀ": {"t": "ᵀ", "d": "Intercambia filas por columnas. Para dos vectores columna, uᵀv es el producto interno: un solo número.", "s": "transpuesta", "l": "matematica/04-producto-interno"}, "∑": {"t": "∑", "d": "Ver Σ.", "s": "suma", "l": "estadistica/01-variables-aleatorias"}, "∫": {"t": "∫", "d": "Suma continua. ∫f(x)dx es el área bajo la curva f; para una densidad, esa área es una probabilidad.", "s": "integral", "l": "estadistica/02-pmf-cdf"}, "∇": {"t": "∇", "d": "El gradiente: el vector de derivadas parciales. Apunta en la dirección de máximo crecimiento de la función.", "s": "nabla", "l": "matematica/06-minimos-cuadrados"}, "∂": {"t": "∂", "d": "Derivada respecto a una variable manteniendo las otras fijas.", "s": "derivada parcial", "l": "matematica/06-minimos-cuadrados"}, "⊥": {"t": "⊥", "d": "Dos vectores son perpendiculares (u ortogonales) si su producto interno es cero.", "s": "perpendicular", "l": "matematica/04-producto-interno"}, "∈": {"t": "∈", "d": "x ∈ A se lee «x pertenece a A» o «x está en A».", "s": "pertenece a", "l": "matematica/01-vectores-y-espacios"}, "ℝ": {"t": "ℝ", "d": "El conjunto de los números reales. ℝⁿ es el espacio de vectores con n coordenadas reales.", "s": "erre", "l": "matematica/01-vectores-y-espacios"}, "∞": {"t": "∞", "d": "No es un número: indica que algo crece sin cota, o que un intervalo no tiene extremo.", "s": "infinito", "l": "estadistica/02-pmf-cdf"}, "≈": {"t": "≈", "d": "Igual hasta un error pequeño. En cómputo suele significar «igual hasta el error de redondeo».", "s": "aproximadamente igual", "l": "python/06-numpy-primer-contacto"}, "∎": {"t": "∎", "d": "Marca el final de una demostración. Equivale a «queda demostrado» (en latín, QED).", "s": "fin de demostración", "l": "estadistica/04-esperanza-varianza-momentos"}, "E[X]": {"t": "E[X]", "d": "El valor esperado de X: su promedio ponderado por la probabilidad. Es un número, no una variable.", "s": "esperanza de equis", "l": "estadistica/04-esperanza-varianza-momentos"}, "n": {"t": "n", "d": "El tamaño de la muestra: cuántos datos se observaron. No confundir con N, que a veces denota el tamaño de la población.", "s": "ene", "l": "estadistica/01-variables-aleatorias"}, "p": {"t": "p", "d": "Según el contexto: una probabilidad, la función de masa p(x), el número de columnas de una matriz de diseño, el valor p de una prueba —que NO es una probabilidad sobre la hipótesis— o un polinomio, como el característico p(λ). Cada lección lo declara en su tabla de notación, que es la que manda.", "s": "pe", "l": "estadistica/02-pmf-cdf"}, "L": {"t": "L", "d": "La función de verosimilitud L(θ): la probabilidad o densidad de los datos observados si el parámetro valiera θ.", "s": "ele", "l": "estadistica/08-maxima-verosimilitud"}, "ℓ": {"t": "ℓ", "d": "La log-verosimilitud, ℓ(θ) = log L(θ). Es la que se maximiza en la práctica.", "s": "ele minúscula", "l": "estadistica/08-maxima-verosimilitud"}, "∏": {"t": "∏", "d": "Símbolo de producto. ∏ᵢ₌₁ⁿ aᵢ significa «multiplica a₁ · a₂ · … · aₙ», igual que Σ los suma.", "s": "productorio", "l": "estadistica/08-maxima-verosimilitud"}, "ν": {"t": "ν", "d": "Grados de libertad de una distribución t o chi cuadrado. Al estimar la media con n datos valen n − 1, porque x̄ ya consumió uno.", "s": "nu", "l": "estadistica/09-intervalos-de-confianza"}, "z": {"t": "z", "d": "El cuantil de la normal estándar. z con subíndice α/2 deja α/2 de probabilidad en la cola derecha: 1.96 al 95 %, 2.576 al 99 %.", "s": "zeta", "l": "estadistica/09-intervalos-de-confianza"}, "F": {"t": "F", "d": "La función acumulada de una distribución. F̂ₙ (con sombrero) es la empírica, calculada a partir de los datos; F sin sombrero, la verdadera y desconocida.", "s": "efe", "l": "estadistica/11-bootstrap"}, "χ": {"t": "χ", "d": "La distribución ji cuadrado. χ²ᵥ es la suma de v normales estándar al cuadrado; su media es v y su varianza 2v.", "s": "ji", "l": "estadistica/12-normal-multivariante"}, "τ": {"t": "τ", "d": "La precisión, es decir 1/σ². En la actualización normal-normal la precisión posterior es τ₀ + nτ: la información de las dos fuentes se suma.", "s": "tau", "l": "estadistica/19-priors-conjugados"}, "∝": {"t": "∝", "d": "«Proporcional a»: igual salvo un factor que no depende de la variable de la que se habla. En Bayes permite descartar la evidencia y quedarse con el núcleo.", "s": "proporcional a", "l": "estadistica/19-priors-conjugados"}};
